def _m23_successor_configured(config: Mapping[str, Any]) -> bool:
    key = "multi_lane_successor_materialization"
    if key not in config:
        return False
    observed = config.get(key)
    expected = _expected_m23_multi_lane_authority()
    if (
        type(observed) is not dict
        or _identity(observed) != _identity(expected)
    ):
        raise MaterializationError("M23 multi-lane successor authority is invalid")
    return True


def _m23_successor_configured_on_any_surface(
    root: Path, config: Mapping[str, Any]
) -> bool:
    key = "multi_lane_successor_materialization"
    cid_key = f"{key}_cid"
    migration = _load_json(
        root / "docs/architecture/semantic_addressed_world_model_inventory/"
        "prior_materialization_migration.json"
    )
    seal = _load_json(
        root / "config/semantic_addressed_world_model_dependencies.seal.json"
    )
    presence = (key in config, key in migration, cid_key in seal)
    if not any(presence):
        return False
    if not all(presence):
        raise MaterializationError("M23 multi-lane authority is only partially declared")
    return _m23_successor_configured(config)


