def _assert_m13_prior_publication_anchor(
    root: Path,
    authority: Mapping[str, Any],
    population: Mapping[str, Any] | None = None,
) -> tuple[Path, Path, dict[str, Any]]:
    """Verify the exact stopped post-failure M12 pair and omitted sidecars."""

    control = _confined_leaf(
        root, str(authority["prior_store_id"]), noun="stopped M12 control store"
    )
    coordination = _confined_leaf(
        root,
        str(authority["prior_coordination_store_id"]),
        noun="stopped M12 coordination store",
    )
    control_wal = control.with_name(control.name + ".wal")
    coordination_wal = coordination.with_name(coordination.name + ".wal")
    read_replica = _confined_leaf(
        root,
        str(authority["prior_read_replica_store_id"]),
        noun="failed M12 read replica",
    )
    owner_status = _confined_leaf(
        root,
        str(authority["prior_owner_status_path"]),
        noun="absent M12 owner status",
    )
    if (
        control.parent != coordination.parent
        or authority["prior_control_wal_present"] is not False
        or authority["prior_coordination_wal_present"] is not False
        or os.path.lexists(control_wal)
        or os.path.lexists(coordination_wal)
        or os.path.lexists(owner_status)
        or os.path.lexists(control.with_name("control.execution.duckdb"))
        or os.path.lexists(control.with_name("control.execution.duckdb.wal"))
        or os.path.lexists(
            control.with_name("control.read-replica.duckdb.wal")
        )
    ):
        raise MigrationRequired("stopped M12 failed-start inventory differs")
    owner_dir = owner_status.parent
    if not owner_dir.is_dir() or tuple(owner_dir.iterdir()):
        raise MigrationRequired("stopped M12 owner directory is not empty")
    anchors = {
        "control": _stable_regular_sha256(
            control, root=root, noun="stopped M12 control store", required_link_count=1
        ),
        "coordination": _stable_regular_sha256(
            coordination,
            root=root,
            noun="stopped M12 coordination store",
            required_link_count=1,
        ),
        "read_replica": _stable_regular_sha256(
            read_replica,
            root=root,
            noun="failed M12 read replica",
            required_link_count=1,
        ),
    }
    if (
        anchors["control"]
        != (
            authority["prior_control_store_sha256"],
            int(authority["prior_control_store_size"]),
        )
        or anchors["coordination"]
        != (
            authority["prior_coordination_store_sha256"],
            int(authority["prior_coordination_store_size"]),
        )
        or anchors["read_replica"]
        != (
            authority["prior_read_replica_store_sha256"],
            int(authority["prior_read_replica_store_size"]),
        )
        or os.stat(control).st_ino == os.stat(read_replica).st_ino
    ):
        raise MigrationRequired("stopped M12 failed-start bytes differ")
    _assert_offline(control)

    receipt, receipt_sha256 = _load_nofollow_json(
        _confined_leaf(
            root,
            str(authority["prior_materialization_receipt_path"]),
            noun="historical M12 publication marker",
        ),
        root=root,
        noun="historical M12 publication marker",
    )
    unhashed = dict(receipt)
    receipt_cid = str(unhashed.pop("receipt_cid", ""))
    if (
        receipt_sha256 != authority["prior_materialization_receipt_file_sha256"]
        or receipt_cid != authority["prior_materialization_receipt_cid"]
        or receipt_cid != _identity(unhashed)
        or receipt.get("schema") != "sawm/non-authoritative-migration-receipt@10"
        or receipt.get("control_store_sha256")
        != authority["prior_publication_control_store_sha256"]
        or receipt.get("projection_cid") != authority["prior_projection_cid"]
        or int(receipt.get("target_event_watermark") or 0) != 189
    ):
        raise MigrationRequired("historical M12 publication marker changed")

    import duckdb
    from ipfs_accelerate_py.agent_supervisor.merge.database_coordination import (
        read_coordination_registry_projection,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_schema import (
        verify_datasets_authoritative_operational_schema,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    with tempfile.TemporaryDirectory(prefix="sawm-r2-m13-prior-", dir="/tmp") as td:
        control_copy = Path(td) / "control.duckdb"
        coordination_copy = Path(td) / "control.coordination.duckdb"
        shutil.copyfile(control, control_copy)
        shutil.copyfile(coordination, coordination_copy)
        schema = verify_datasets_authoritative_operational_schema(control_copy)
        connection = duckdb.connect(str(control_copy), read_only=True)
        try:
            prefix = _event_prefix_digest(
                connection, int(authority["prior_event_watermark"])
            )
            catalog = _main_catalog_digest_on(connection)
            max_generation = int(
                connection.execute(
                    "SELECT COALESCE(MAX(generation), 0) FROM store_generations"
                ).fetchone()[0]
            )
        finally:
            connection.close()
        source = DatabaseTaskSource(control_copy, install_schema=False)
        try:
            snapshot = source.snapshot()
            operator = source.get_task("SAWM-000")
            candidate = source.get_task("SAWM-001")
            plan = (
                source.get_plan(str(population["plan_root_cid"]))
                if population is not None
                else None
            )
            if (
                schema.get("valid") is not True
                or prefix
                != (
                    authority["prior_event_prefix_sha256"],
                    int(authority["prior_event_watermark"]),
                )
                or catalog != authority["prior_catalog_digest"]
                or max_generation != int(authority["prior_generation"])
                or snapshot.event_cursor != 189
                or snapshot.projection_cid != authority["prior_projection_cid"]
                or operator is None
                or operator.status != "completed"
                or operator.revision != 2
                or candidate is None
                or candidate.status != "retrying"
                or candidate.revision != 16
                or dict(candidate.body).get("completion_receipt")
                != _m12_task_rearm_receipt()
                or (
                    population is not None
                    and (
                        plan is None
                        or int(plan.get("revision") or 0)
                        != int(authority["prior_plan_revision"])
                    )
                )
                or not source.projection_matches_events()
            ):
                raise MigrationRequired("stopped M12 logical authority differs")
        finally:
            source.close()
        coordination_projection = read_coordination_registry_projection(
            coordination_copy
        )
        if (
            coordination_projection.get("projection_root")
            != authority["prior_coordination_projection_digest"]
        ):
            raise MigrationRequired("stopped M12 coordination projection differs")
    if (
        _semantic_authority_digest(control) != authority["prior_semantic_authority_digest"]
        or _frozen_base_authority_digest(control)
        != authority["prior_frozen_base_authority_digest"]
        or _append_surface_digest(control) != authority["prior_append_surface_digest"]
        or any(
            _stable_regular_sha256(path, root=root, noun=name, required_link_count=1)
            != anchors[key]
            for key, path, name in (
                ("control", control, "stopped M12 control store after verification"),
                (
                    "coordination",
                    coordination,
                    "stopped M12 coordination store after verification",
                ),
                (
                    "read_replica",
                    read_replica,
                    "failed M12 read replica after verification",
                ),
            )
        )
    ):
        raise MigrationRequired("stopped M12 authority changed during verification")
    return control, coordination, {
        "valid": True,
        "event_watermark": 189,
        "projection_cid": authority["prior_projection_cid"],
        "coordination_event_count": 224,
        "coordination_projection_digest": authority[
            "prior_coordination_projection_digest"
        ],
        "receipt": receipt,
    }


def _verify_m13_store_pair_copy(
    control: Path,
    coordination: Path,
    prior_control: Path,
    prior_coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Verify M13's two-event source append and unchanged coordination."""

    authority = _m13_quack_refresh_authority(population, config)
    hashes = {
        "control": _store_sha256(control),
        "coordination": _store_sha256(coordination),
        "prior_control": _store_sha256(prior_control),
        "prior_coordination": _store_sha256(prior_coordination),
    }
    if (
        hashes["prior_control"] != authority["prior_control_store_sha256"]
        or hashes["prior_coordination"]
        != authority["prior_coordination_store_sha256"]
        or hashes["coordination"] != hashes["prior_coordination"]
        or any(
            os.path.lexists(path)
            for path in (
                control.with_name(control.name + ".wal"),
                coordination.with_name(coordination.name + ".wal"),
            )
        )
    ):
        raise MigrationRequired("M13 staged predecessor or sidecar bytes differ")
    expected_body = _m13_migration_body(population, config, validation_digest)
    expected_digest = _identity(expected_body)
    expected_delta = _m13_migration_plan_delta(population, config)

    import duckdb
    from ipfs_accelerate_py.agent_supervisor.merge.database_coordination import (
        read_coordination_registry_projection,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    prior = duckdb.connect(str(prior_control), read_only=True)
    target = duckdb.connect(str(control), read_only=True)
    try:
        append_tables = {"plans", "plan_revisions", "evidence_nodes", "domain_events"}
        prior_tables = _main_table_names(prior)
        target_tables = _main_table_names(target)
        if (
            prior_tables != target_tables
            or _main_catalog_digest_on(prior) != authority["prior_catalog_digest"]
            or _main_catalog_digest_on(target) != authority["prior_catalog_digest"]
            or _authority_table_digest_on(
                prior, tuple(table for table in prior_tables if table not in append_tables)
            )
            != _authority_table_digest_on(
                target, tuple(table for table in target_tables if table not in append_tables)
            )
        ):
            raise MigrationRequired("M13 changed frozen control authority")
        rows: dict[str, tuple[list[tuple[Any, ...]], list[tuple[Any, ...]]]] = {}
        for table, width, order in (
            ("plans", 8, "1,2"),
            ("plan_revisions", 4, "1,2,3,4"),
            ("evidence_nodes", 7, "1,2,3,4,5,6,7"),
        ):
            rows[table] = (
                _positional_rows(prior.execute(f"SELECT * FROM {table} ORDER BY {order}").fetchall(), width),
                _positional_rows(target.execute(f"SELECT * FROM {table} ORDER BY {order}").fetchall(), width),
            )
        event_sql = (
            "SELECT event_id,stream_id,sequence,global_sequence,event_type,"
            "task_cid,attempt_id,session_id,recorded_at,body_json "
            "FROM domain_events ORDER BY global_sequence"
        )
        prior_events = _positional_rows(prior.execute(event_sql).fetchall(), 10)
        target_events = _positional_rows(target.execute(event_sql).fetchall(), 10)
    finally:
        target.close()
        prior.close()
    prior_plans, target_plans = rows["plans"]
    prior_revisions, target_revisions = rows["plan_revisions"]
    prior_evidence, target_evidence = rows["evidence_nodes"]
    if (
        len(prior_plans) != len(target_plans) != 0
        or len(prior_plans) != 1
        or len(target_revisions) != len(prior_revisions) + 1
        or target_revisions[:-1] != prior_revisions
        or len(target_evidence) != len(prior_evidence) + 1
        or target_events[:-2] != prior_events
        or len(prior_events) != 189
        or len(target_events) != 191
    ):
        raise MigrationRequired("M13 append-only surface counts differ")
    prior_plan, target_plan = prior_plans[0], target_plans[0]
    expected_plan_body = {
        **json.loads(str(prior_plan[7])),
        "current_source_binding_cid": population["source_binding"]["source_binding_cid"],
        "source_migration_revision": _M13_MIGRATION_REVISION,
        "source_migration_digest": expected_digest,
        "supersession_mode": _M13_SUPERSESSION_MODE,
        "last_delta": expected_delta,
    }
    expected_evidence_id = content_identity(
        {
            "task_cid": population["migration_inventory"]["prior_task_cids"]["SAWM-000"],
            "evidence_kind": "operator_control_plane_source_migration",
            "digest": expected_digest,
            "body": expected_body,
        }
    )
    prior_evidence_map = {str(row[0]): row for row in prior_evidence}
    target_evidence_map = {str(row[0]): row for row in target_evidence}
    new_evidence = target_evidence_map.get(expected_evidence_id)
    if (
        any(target_evidence_map.get(key) != row for key, row in prior_evidence_map.items())
        or set(target_evidence_map) - set(prior_evidence_map) != {expected_evidence_id}
        or new_evidence is None
        or prior_plan[:5] != target_plan[:5]
        or int(prior_plan[6]) != 13
        or int(target_plan[6]) != 14
        or json.loads(str(target_plan[7])) != expected_plan_body
        or target_revisions[-1]
        != (
            str(population["plan_root_cid"]),
            14,
            _canonical(expected_plan_body).decode("utf-8"),
            str(target_plan[5]),
        )
        or str(new_evidence[2])
        != population["migration_inventory"]["prior_task_cids"]["SAWM-000"]
        or str(new_evidence[3]) != "operator_control_plane_source_migration"
        or str(new_evidence[4]) != expected_digest
        or str(new_evidence[5]) != _M13_CONTROL_RECORDED_AT
        or json.loads(str(new_evidence[6])) != expected_body
    ):
        raise MigrationRequired("M13 plan/evidence append differs")
    events: list[dict[str, Any]] = []
    for row in target_events[-2:]:
        envelope = json.loads(str(row[9]))
        event = {
            "id": str(row[0]), "stream": str(row[1]), "sequence": int(row[2]),
            "global": int(row[3]), "type": str(row[4]), "task": str(row[5]),
            "attempt": str(row[6]), "session": str(row[7]),
            "recorded_at": str(row[8]), "body": envelope,
        }
        if (
            content_identity(
                {
                    "stream_id": event["stream"], "sequence": event["sequence"],
                    "global_sequence": event["global"], "event_type": event["type"],
                    "body": envelope,
                }
            ) != event["id"]
            or event["stream"] != "stream:intent"
            or event["sequence"] != event["global"]
            or event["attempt"]
            or event["session"] != "session:intent"
            or event["recorded_at"] != _M13_CONTROL_RECORDED_AT
            or envelope.get("owner_id") != "sawm-r2-quack-refresh-migrator"
        ):
            raise MigrationRequired("M13 event identity differs")
        events.append(event)
    if (
        [event["type"] for event in events]
        != ["intent.plan_revision_appended", "intent.evidence_recorded"]
        or [event["global"] for event in events] != [190, 191]
        or events[0]["body"].get("body", {}).get("body") != expected_plan_body
        or events[1]["body"].get("subject_id") != expected_evidence_id
        or events[1]["body"].get("body", {}).get("body") != expected_body
    ):
        raise MigrationRequired("M13 event bodies differ")
    semantic = _semantic_authority_digest(control)
    frozen = _frozen_base_authority_digest(control)
    append = _append_surface_digest(control)
    if (
        semantic != authority["target_semantic_authority_digest"]
        or frozen != authority["target_frozen_base_authority_digest"]
    ):
        raise MigrationRequired("M13 changed semantic authority")
    with tempfile.TemporaryDirectory(prefix="sawm-r2-m13-replay-", dir="/tmp") as td:
        replay_control = Path(td) / "control.duckdb"
        shutil.copyfile(control, replay_control)
        source = DatabaseTaskSource(replay_control, install_schema=False)
        try:
            snapshot = source.snapshot()
            candidate = source.get_task("SAWM-001")
            if (
                snapshot.event_cursor != _M13_TARGET_EVENT_WATERMARK
                or snapshot.projection_cid != _M13_EXPECTED_PROJECTION_CID
                or candidate is None
                or candidate.status != "retrying"
                or candidate.revision != 16
                or dict(candidate.body).get("completion_receipt")
                != _m12_task_rearm_receipt()
                or not source.projection_matches_events()
            ):
                raise MigrationRequired("M13 replay projection differs")
        finally:
            source.close()
    prior_coord_projection = read_coordination_registry_projection(prior_coordination)
    target_coord_projection = read_coordination_registry_projection(coordination)
    if (
        target_coord_projection != prior_coord_projection
        or target_coord_projection.get("projection_root")
        != authority["target_coordination_projection_digest"]
    ):
        raise MigrationRequired("M13 changed coordination semantics")
    if any(
        _store_sha256(path) != hashes[key]
        for key, path in (
            ("control", control), ("coordination", coordination),
            ("prior_control", prior_control), ("prior_coordination", prior_coordination),
        )
    ):
        raise MaterializationError("M13 verifier mutated a store")
    return {
        "valid": True,
        "task_count": 45,
        "goal_count": 29,
        "projection_cid": _M13_EXPECTED_PROJECTION_CID,
        "event_watermark": _M13_TARGET_EVENT_WATERMARK,
        "projection_matches_events": True,
        "migration_digest": expected_digest,
        "migration_evidence_id": expected_evidence_id,
        "plan_migration_event_id": events[0]["id"],
        "migration_evidence_event_id": events[1]["id"],
        "semantic_authority_digest": semantic,
        "frozen_base_authority_digest": frozen,
        "append_surface_digest": append,
        "coordination_projection_digest": target_coord_projection["projection_root"],
        "coordination_event_count": 224,
        "control_store_sha256": hashes["control"],
        "coordination_store_sha256": hashes["coordination"],
        "plan_revision_changes": 1,
        "evidence_node_changes": 1,
        "task_revision_changes": 0,
        "task_status_changes": 0,
        "accepted_definition_changes": 0,
        "accepted_completion_changes": 0,
        "coordination_semantic_changes": 0,
    }


def _verify_m13_store_pair(
    root: Path,
    control: Path,
    coordination: Path,
    prior_control: Path,
    prior_coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Verify M13 published bytes only through disposable exact copies."""

    _assert_offline(control)
    initial = {
        "control": _stable_regular_sha256(
            control, root=root, noun="published M13 control store", required_link_count=1
        ),
        "coordination": _stable_regular_sha256(
            coordination,
            root=root,
            noun="published M13 coordination store",
            required_link_count=1,
        ),
    }
    with tempfile.TemporaryDirectory(prefix="sawm-r2-m13-verify-", dir="/tmp") as td:
        copies = [Path(td) / name for name in (
            "control.duckdb", "control.coordination.duckdb",
            "prior-control.duckdb", "prior-control.coordination.duckdb",
        )]
        for source_path, copy_path in zip(
            (control, coordination, prior_control, prior_coordination), copies, strict=True
        ):
            shutil.copyfile(source_path, copy_path)
        report = _verify_m13_store_pair_copy(
            *copies, population, config, validation_digest
        )
    if (
        _stable_regular_sha256(
            control, root=root, noun="published M13 control store", required_link_count=1
        ) != initial["control"]
        or _stable_regular_sha256(
            coordination,
            root=root,
            noun="published M13 coordination store",
            required_link_count=1,
        ) != initial["coordination"]
    ):
        raise MaterializationError("M13 verification changed published bytes")
    return {
        **report,
        "control_store_sha256": initial["control"][0],
        "coordination_store_sha256": initial["coordination"][0],
    }


def _expected_m13_migration_receipt(
    root: Path,
    control: Path,
    coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    verified: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Build M13's receipt-last non-authoritative pair marker."""

    authority = _m13_quack_refresh_authority(population, config)
    control_hash = _stable_regular_sha256(
        control, root=root, noun="published M13 control store", required_link_count=1
    )
    coordination_hash = _stable_regular_sha256(
        coordination,
        root=root,
        noun="published M13 coordination store",
        required_link_count=1,
    )
    if (
        control_hash[0] != verified.get("control_store_sha256")
        or coordination_hash[0] != verified.get("coordination_store_sha256")
        or verified.get("projection_cid") != authority["target_projection_cid"]
        or int(verified.get("event_watermark") or 0)
        != authority["target_event_watermark"]
        or verified.get("semantic_authority_digest")
        != authority["target_semantic_authority_digest"]
        or verified.get("frozen_base_authority_digest")
        != authority["target_frozen_base_authority_digest"]
        or verified.get("coordination_projection_digest")
        != authority["target_coordination_projection_digest"]
    ):
        raise MigrationRequired("M13 pair changed before receipt construction")
    receipt = {
        "schema": "sawm/non-authoritative-migration-receipt@11",
        "authoritative": False,
        "control_database_is_authority": True,
        "coordination_database_is_authority": True,
        "receipt_is_final_pair_commit_marker": True,
        "migration_revision": _M13_MIGRATION_REVISION,
        "program_definition_cid": population["program_definition_cid"],
        "plan_projection_cid": authority["prior_projection_cid"],
        "migration_projection_cid": verified["projection_cid"],
        "migration_event_watermark": verified["event_watermark"],
        "projection_cid": verified["projection_cid"],
        "target_event_watermark": authority["target_event_watermark"],
        "target_generation": authority["target_generation"],
        "target_quack_port": authority["target_quack_port"],
        "validation_digest": validation_digest,
        "migration_digest": verified["migration_digest"],
        "migration_evidence_id": verified["migration_evidence_id"],
        "plan_migration_event_id": verified["plan_migration_event_id"],
        "migration_evidence_event_id": verified["migration_evidence_event_id"],
        "coordination_projection_digest": verified[
            "coordination_projection_digest"
        ],
        "coordination_event_count": verified["coordination_event_count"],
        "control_store_sha256": control_hash[0],
        "control_store_size": control_hash[1],
        "coordination_store_sha256": coordination_hash[0],
        "coordination_store_size": coordination_hash[1],
        "semantic_authority_digest": verified["semantic_authority_digest"],
        "frozen_base_authority_digest": verified[
            "frozen_base_authority_digest"
        ],
        "append_surface_digest": verified["append_surface_digest"],
        "prior_database_path": authority["prior_store_id"],
        "prior_coordination_path": authority["prior_coordination_store_id"],
        "database_path": str(control.relative_to(root)),
        "coordination_path": str(coordination.relative_to(root)),
        "prior_publication_control_store_sha256": authority[
            "prior_publication_control_store_sha256"
        ],
        "prior_control_store_sha256": authority["prior_control_store_sha256"],
        "prior_coordination_store_sha256": authority[
            "prior_coordination_store_sha256"
        ],
        "prior_control_wal_present": False,
        "prior_coordination_wal_present": False,
        "prior_owner_status_present": False,
        "prior_read_replica_store_sha256": authority[
            "prior_read_replica_store_sha256"
        ],
        "prior_read_replica_is_authority": False,
        "prior_read_replica_copied": False,
        "prior_event_prefix_sha256": authority["prior_event_prefix_sha256"],
        "prior_source_binding_cid": authority["prior_source_binding_cid"],
        "current_source_binding_cid": population["source_binding"][
            "source_binding_cid"
        ],
        "prior_materialization_receipt_cid": authority[
            "prior_materialization_receipt_cid"
        ],
        "prior_materialization_receipt_precedes_failed_start_checkpoint": True,
        "declared_output_retry_successor_materialization_cid": (
            _M12_DECLARED_OUTPUT_RETRY_AUTHORITY_CID
        ),
        "quack_refresh_successor_materialization_cid": (
            _M13_QUACK_REFRESH_AUTHORITY_CID
        ),
        "failed_quack_start_cid": authority["failed_quack_start_cid"],
        "control_and_coordination_bases_copied": True,
        "prior_wals_absent": True,
        "prior_control_store_mutated": False,
        "prior_coordination_store_mutated": False,
        "prior_failed_start_artifacts_preserved": True,
        "plan_revision_changes": 1,
        "evidence_node_changes": 1,
        "coordination_semantic_changes": 0,
        "task_revision_changes": 0,
        "task_status_changes": 0,
        "accepted_definition_changes": 0,
        "accepted_completion_changes": 0,
        "implementation_provider_invocations": 0,
        "execution_sidecar_copied": False,
        "read_replica_sidecar_copied": False,
        "effect_claim_changes": 0,
        "implementation_commit_changes": 0,
        "merge_attempt_changes": 0,
        "worker_self_approval": False,
    }
    return {**receipt, "receipt_cid": _identity(receipt)}


def _assert_m13_receipt_commit_inputs(
    root: Path,
    control: Path,
    coordination: Path,
    expected: Mapping[str, Any],
) -> None:
    """Rehash M13's exact offline pair and reject all mutable sidecars."""

    sidecars = (
        control.with_name("control.execution.duckdb"),
        control.with_name("control.execution.duckdb.wal"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name("control.read-replica.duckdb.wal"),
        control.with_name(control.name + ".wal"),
        coordination.with_name(coordination.name + ".wal"),
    )
    if any(os.path.lexists(path) for path in sidecars):
        raise MigrationRequired("M13 mutable sidecar appeared before final receipt")
    def exact() -> tuple[tuple[str, int], tuple[str, int]]:
        return (
            _stable_regular_sha256(
                control,
                root=root,
                noun="M13 receipt control store",
                required_link_count=1,
            ),
            _stable_regular_sha256(
                coordination,
                root=root,
                noun="M13 receipt coordination store",
                required_link_count=1,
            ),
        )
    before = exact()
    _assert_offline(control)
    if any(os.path.lexists(path) for path in sidecars):
        raise MigrationRequired("M13 mutable sidecar appeared before final receipt")
    after = exact()
    expected_pair = (
        (str(expected["control_store_sha256"]), int(expected["control_store_size"])),
        (
            str(expected["coordination_store_sha256"]),
            int(expected["coordination_store_size"]),
        ),
    )
    if before != after or after != expected_pair:
        raise MigrationRequired("M13 store pair changed at receipt commit")


def _ensure_m13_migration_receipt(
    root: Path,
    control: Path,
    coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    verified: Mapping[str, Any],
    validation_digest: str,
    *,
    pair_lock_held: bool = False,
) -> dict[str, Any]:
    """Publish M13's exact marker last and recover one pending hardlink."""

    pair_lock = control.parent / ".m13-store-pair.publish.lock"
    descriptor = os.open(
        pair_lock, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600
    )
    try:
        if not pair_lock_held:
            lock_stat = os.fstat(descriptor)
            if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
                raise MaterializationError("M13 receipt lock is not a regular file")
            deadline = time.monotonic() + 10.0
            while True:
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    break
                except BlockingIOError as exc:
                    if time.monotonic() >= deadline:
                        raise MaterializationError(
                            "timed out acquiring the M13 receipt lock"
                        ) from exc
                    time.sleep(0.02)
        authority = _m13_quack_refresh_authority(population, config)
        _assert_committed_clean_source(root, population)
        _assert_m13_source_delta(root, population, authority)
        prior_control, prior_coordination, _ = _assert_m13_prior_publication_anchor(
            root, authority, population
        )
        current = _verify_m13_store_pair(
            root,
            control,
            coordination,
            prior_control,
            prior_coordination,
            population,
            config,
            validation_digest,
        )
        if dict(current) != dict(verified):
            raise MigrationRequired("M13 pair changed before receipt publication")
        expected = _expected_m13_migration_receipt(
            root, control, coordination, population, config, current, validation_digest
        )
        receipt_path = control.parent / "migration-receipt.json"
        pending = sorted(receipt_path.parent.glob(f".{receipt_path.name}.*.tmp"))
        _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
        if os.path.lexists(receipt_path):
            observed, _ = _load_nofollow_json(
                receipt_path, root=root, noun="M13 final pair marker"
            )
            if observed != expected:
                raise MigrationRequired("M13 final pair marker differs")
            receipt_stat = os.lstat(receipt_path)
            aliases = [
                path
                for path in pending
                if os.lstat(path).st_ino == receipt_stat.st_ino
                and os.lstat(path).st_dev == receipt_stat.st_dev
            ]
            if receipt_stat.st_nlink == 2 and len(aliases) == 1 and len(pending) == 1:
                os.unlink(aliases[0])
            elif receipt_stat.st_nlink != 1 or pending:
                raise MigrationRequired("M13 receipt alias population differs")
            _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
            return observed
        if len(pending) > 1:
            raise MigrationRequired("M13 has ambiguous pending receipt files")
        temporary = pending[0] if pending else receipt_path.with_name(
            f".{receipt_path.name}.{os.getpid()}.tmp"
        )
        if pending:
            observed, _ = _load_nofollow_json(
                temporary, root=root, noun="pending M13 migration receipt"
            )
            if observed != expected:
                raise MigrationRequired("pending M13 receipt differs")
        else:
            out = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                0o600,
            )
            try:
                payload = _canonical(expected) + b"\n"
                os.write(out, payload)
                os.fsync(out)
            finally:
                os.close(out)
        _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
        os.link(temporary, receipt_path, follow_symlinks=False)
        _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
        os.unlink(temporary)
        observed, _ = _load_nofollow_json(
            receipt_path, root=root, noun="committed M13 migration receipt"
        )
        if observed != expected:
            raise MigrationRequired("committed M13 receipt differs")
        return observed
    finally:
        if not pair_lock_held:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError:
                pass
        os.close(descriptor)


def _verify_existing_m13_migration_receipt(
    root: Path,
    control: Path,
    coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    verified: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    expected = _expected_m13_migration_receipt(
        root, control, coordination, population, config, verified, validation_digest
    )
    _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
    observed, _ = _load_nofollow_json(
        control.parent / "migration-receipt.json",
        root=root,
        noun="M13 final pair marker",
    )
    if observed != expected:
        raise MigrationRequired("M13 final pair marker differs")
    unhashed = dict(observed)
    if str(unhashed.pop("receipt_cid", "")) != _identity(unhashed):
        raise MigrationRequired("M13 final pair marker CID does not rehash")
    _assert_m13_receipt_commit_inputs(root, control, coordination, expected)
    return observed


def _stage_m13_store_pair(
    root: Path,
    stage_dir: Path,
    prior_control: Path,
    prior_coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Build M13 privately from exact stopped-M12 base bytes."""

    authority = _m13_quack_refresh_authority(population, config)
    stage_control = stage_dir / "control.duckdb"
    stage_coordination = stage_dir / "control.coordination.duckdb"
    shutil.copy2(prior_control, stage_control)
    shutil.copy2(prior_coordination, stage_coordination)
    if (
        _store_sha256(stage_control) != authority["prior_control_store_sha256"]
        or _store_sha256(stage_coordination)
        != authority["prior_coordination_store_sha256"]
    ):
        raise MaterializationError("staged M12 pair differs before M13 migration")

    from ipfs_accelerate_py.agent_supervisor.task_sources import intent_repository
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    original_clock = intent_repository._utc_iso

    def fixed_m13_utc_iso(_moment: Any = None) -> str:
        return _M13_CONTROL_RECORDED_AT

    intent_repository._utc_iso = fixed_m13_utc_iso
    clock_interference = False
    try:
        source = DatabaseTaskSource(
            stage_control,
            install_schema=False,
            repository_tree_id=str(population["repository_tree_id"]),
            plan_root_cid=str(population["plan_root_cid"]),
            owner_id="sawm-r2-quack-refresh-migrator",
        )
        try:
            operator = source.get_task("SAWM-000")
            candidate = source.get_task("SAWM-001")
            if (
                operator is None
                or operator.status != "completed"
                or operator.revision != 2
                or candidate is None
                or candidate.status != "retrying"
                or candidate.revision != 16
                or dict(candidate.body).get("completion_receipt")
                != _m12_task_rearm_receipt()
            ):
                raise MaterializationError("staged M12 task authority differs")
            migration_body = _m13_migration_body(
                population, config, validation_digest
            )
            migration_digest = _identity(migration_body)
            plan_receipt = source.plans.append_revision(
                plan_cid=str(population["plan_root_cid"]),
                expected_revision=13,
                body={
                    "current_source_binding_cid": population["source_binding"][
                        "source_binding_cid"
                    ],
                    "source_migration_revision": _M13_MIGRATION_REVISION,
                    "source_migration_digest": migration_digest,
                    "supersession_mode": _M13_SUPERSESSION_MODE,
                },
                delta=_m13_migration_plan_delta(population, config),
            )
            evidence = source.record_evidence(
                task_cid=operator.task_cid,
                evidence_kind="operator_control_plane_source_migration",
                digest=migration_digest,
                body=migration_body,
            )
            unchanged = source.get_task("SAWM-001")
            if (
                unchanged is None
                or unchanged.status != "retrying"
                or unchanged.revision != 16
                or dict(unchanged.body).get("completion_receipt")
                != _m12_task_rearm_receipt()
            ):
                raise MaterializationError("M13 source append changed task authority")
        finally:
            source.close()
    finally:
        clock_interference = intent_repository._utc_iso is not fixed_m13_utc_iso
        intent_repository._utc_iso = original_clock
    if clock_interference or intent_repository._utc_iso is not original_clock:
        raise MaterializationError("M13 deterministic control clock binding drifted")
    if any(
        os.path.lexists(path)
        for path in (
            stage_control.with_name(stage_control.name + ".wal"),
            stage_coordination.with_name(stage_coordination.name + ".wal"),
        )
    ):
        raise MaterializationError("M13 mutation retained a WAL")
    verified = _verify_m13_store_pair_copy(
        stage_control,
        stage_coordination,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    return {
        "stage_control": stage_control,
        "stage_coordination": stage_coordination,
        "plan_receipt": plan_receipt,
        "evidence": evidence,
        "migration_digest": migration_digest,
        "verified": verified,
    }


def _check_m13_materialized(
    repo_root: Path | str = REPO_ROOT,
    config_path: Path | str = CONFIG_PATH,
) -> dict[str, Any]:
    """Verify M13 and its receipt-last marker without mutation."""

    root = Path(repo_root).resolve()
    config_file = Path(config_path)
    if not config_file.is_absolute():
        config_file = root / config_file
    config = _load_json(config_file)
    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m13_quack_refresh_authority(population, config)
    _assert_m13_source_delta(root, population, authority)
    control, coordination = _m13_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    if not all(os.path.lexists(path) for path in (control, coordination, receipt_path)):
        raise MigrationRequired("M13 materialized pair or final marker is missing")
    if any(
        os.path.lexists(path)
        for path in (
            control.with_name("control.execution.duckdb"),
            control.with_name("control.execution.duckdb.wal"),
            control.with_name("control.read-replica.duckdb"),
            control.with_name("control.read-replica.duckdb.wal"),
            control.with_name(control.name + ".wal"),
            coordination.with_name(coordination.name + ".wal"),
            control.with_name(f".{control.name}.state-owner.json"),
        )
    ):
        raise MigrationRequired("M13 materialized authority has a forbidden sidecar")
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination, prior = _assert_m13_prior_publication_anchor(
        root, authority, population
    )
    verified = _verify_m13_store_pair(
        root,
        control,
        coordination,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    receipt = _verify_existing_m13_migration_receipt(
        root, control, coordination, population, config, verified, validation_digest
    )
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "checked",
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "receipt": receipt,
        **verified,
    }


def _materialize_m13(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append M13 source evidence and publish an unchanged coordinator."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m13_quack_refresh_authority(population, config)
    _assert_m13_source_delta(root, population, authority)
    control, coordination = _m13_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination, prior = _assert_m13_prior_publication_anchor(
        root, authority, population
    )
    control_present = os.path.lexists(control)
    coordination_present = os.path.lexists(coordination)
    receipt_present = os.path.lexists(receipt_path)
    if control_present != coordination_present:
        raise MigrationRequired(
            "M13 has a partial published store pair without a final marker"
        )
    if receipt_present and not control_present:
        raise MigrationRequired("M13 has an orphaned pair commit marker")
    if control_present:
        return _check_m13_materialized(root, config_file)
    prohibited = (
        control,
        coordination,
        receipt_path,
        control.with_name("control.execution.duckdb"),
        control.with_name("control.execution.duckdb.wal"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name("control.read-replica.duckdb.wal"),
        control.with_name(control.name + ".wal"),
        coordination.with_name(coordination.name + ".wal"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "quack-owner",
    )
    unexpected = [str(path) for path in prohibited if os.path.lexists(path)]
    if unexpected:
        raise MaterializationError(
            "M13 successor operational authority is not fresh: "
            + json.dumps(unexpected, sort_keys=True, separators=(",", ":"))
        )
    control.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(control.parent.glob(".m13-installing.*"))
    pending_receipts = sorted(
        control.parent.glob(f".{receipt_path.name}.*.tmp")
    )
    if preserved_stages or pending_receipts:
        raise MaterializationError(
            "preserved M13 staging/receipt attempt requires inspection: "
            + ", ".join(
                str(item) for item in (*preserved_stages, *pending_receipts)
            )
        )
    stage_dir = control.parent / f".m13-installing.{os.getpid()}.{validation_digest[-12:]}"
    os.mkdir(stage_dir, 0o700)
    staged = _stage_m13_store_pair(
        root,
        stage_dir,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    stage_control = staged["stage_control"]
    stage_coordination = staged["stage_coordination"]
    staged_verified = staged["verified"]

    _assert_committed_clean_source(root, population)
    _assert_m13_source_delta(root, population, authority)
    _assert_m13_prior_publication_anchor(root, authority, population)
    for stage_path in (stage_control, stage_coordination):
        with stage_path.open("rb") as staged_file:
            os.fsync(staged_file.fileno())

    lock_path = control.parent / ".m13-store-pair.publish.lock"
    descriptor = os.open(
        lock_path, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600
    )
    created: list[tuple[Path, int, int]] = []
    stage_aliases_removed = False
    committed = False
    receipt: dict[str, Any] | None = None
    published: dict[str, Any] | None = None
    try:
        lock_stat = os.fstat(descriptor)
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
            raise MaterializationError("M13 bundle lock is not a regular file")
        deadline = time.monotonic() + 10.0
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise MaterializationError(
                        "timed out acquiring the M13 pair publication lock"
                    ) from exc
                time.sleep(0.02)
        if any(os.path.lexists(path) for path in (control, coordination, receipt_path)):
            raise MigrationRequired("another writer published part of the M13 pair")
        _assert_committed_clean_source(root, population)
        _assert_m13_source_delta(root, population, authority)
        _assert_m13_prior_publication_anchor(root, authority, population)
        directory = os.open(
            control.parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            stage_control_stat = os.lstat(stage_control)
            os.link(stage_control, control, follow_symlinks=False)
            created.append(
                (control, stage_control_stat.st_dev, stage_control_stat.st_ino)
            )
            os.fsync(directory)
            stage_coordination_stat = os.lstat(stage_coordination)
            os.link(stage_coordination, coordination, follow_symlinks=False)
            created.append(
                (
                    coordination,
                    stage_coordination_stat.st_dev,
                    stage_coordination_stat.st_ino,
                )
            )
            os.fsync(directory)
            _assert_committed_clean_source(root, population)
            _assert_m13_source_delta(root, population, authority)
            _assert_m13_prior_publication_anchor(root, authority, population)

            removable_names = {
                "control.duckdb",
                "control.coordination.duckdb",
                ".control.duckdb.intent.lock",
                ".control.duckdb.lock",
                ".control.coordination.duckdb.lock",
            }
            stage_entries = tuple(stage_dir.iterdir())
            unexpected_stage = sorted(
                path.name
                for path in stage_entries
                if path.name not in removable_names
            )
            if unexpected_stage:
                raise MaterializationError(
                    "M13 staging directory has unexpected leaves: "
                    + ", ".join(unexpected_stage)
                )
            for path in stage_entries:
                leaf_stat = os.lstat(path)
                if not stat.S_ISREG(leaf_stat.st_mode):
                    raise MaterializationError(
                        "M13 staging leaf changed before alias removal"
                    )
            for path in stage_entries:
                os.unlink(path)
            stage_dir.rmdir()
            os.fsync(directory)
            stage_aliases_removed = True
            if any(
                os.path.lexists(path)
                for path in (
                    control.with_name("control.execution.duckdb"),
                    control.with_name("control.execution.duckdb.wal"),
                    control.with_name("control.read-replica.duckdb"),
                    control.with_name("control.read-replica.duckdb.wal"),
                    control.with_name(control.name + ".wal"),
                    coordination.with_name(coordination.name + ".wal"),
                    control.with_name(f".{control.name}.state-owner.json"),
                )
            ):
                raise MigrationRequired(
                    "M13 mutable sidecar appeared before pair admission"
                )
            published = _verify_m13_store_pair(
                root,
                control,
                coordination,
                prior_control,
                prior_coordination,
                population,
                config,
                validation_digest,
            )
            if dict(published) != dict(staged_verified):
                raise MigrationRequired("published M13 pair differs from staging")
            receipt = _ensure_m13_migration_receipt(
                root,
                control,
                coordination,
                population,
                config,
                published,
                validation_digest,
                pair_lock_held=True,
            )
            committed = True
        finally:
            os.close(directory)
    except Exception:
        if (
            not committed
            and not stage_aliases_removed
            and not os.path.lexists(receipt_path)
        ):
            rollback_directory = os.open(
                control.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                for published_path, expected_device, expected_inode in reversed(created):
                    if not os.path.lexists(published_path):
                        continue
                    published_stat = os.lstat(published_path)
                    if (
                        published_stat.st_dev == expected_device
                        and published_stat.st_ino == expected_inode
                    ):
                        os.unlink(published_path)
                os.fsync(rollback_directory)
            finally:
                os.close(rollback_directory)
        raise
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)
    if not committed or receipt is None or published is None:
        raise MaterializationError("M13 pair publication lacked its final marker")
    if not stage_aliases_removed:
        raise MaterializationError("M13 receipt preceded staging-alias removal")
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only_control_and_unchanged_coordination",
        "migration_required": False,
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "plan_migration_event_id": staged["plan_receipt"].event_id,
        "migration_evidence_event_id": staged["evidence"].event_id,
        "migration_digest": staged["migration_digest"],
        "stage_cleanup_complete": True,
        "receipt": receipt,
        **published,
    }


def check_materialized(
    repo_root: Path | str = REPO_ROOT,
    config_path: Path | str = CONFIG_PATH,
) -> dict[str, Any]:
    """Verify the newest configured append-only materialization authority."""

    root = Path(repo_root).resolve()
    config_file = Path(config_path)
    if not config_file.is_absolute():
        config_file = root / config_file
    config = _load_json(config_file)
    if _m34_successor_configured_on_any_surface(root, config):
        return _check_m34_materialized(root, config_file)
    if _m33_successor_configured_on_any_surface(root, config):
        return _check_m33_materialized(root, config_file)
    if _m32_successor_configured_on_any_surface(root, config):
        return _check_m32_materialized(root, config_file)
    if _m31_successor_configured_on_any_surface(root, config):
        return _check_m31_materialized(root, config_file)
    if _m30_successor_configured_on_any_surface(root, config):
        return _check_m30_materialized(root, config_file)
    if _m29_successor_configured_on_any_surface(root, config):
        return _check_m29_materialized(root, config_file)
    if _m28_successor_configured_on_any_surface(root, config):
        return _check_m28_materialized(root, config_file)
    if _m27_successor_configured_on_any_surface(root, config):
        return _check_m27_materialized(root, config_file)
    if _m26_successor_configured_on_any_surface(root, config):
        return _check_m26_materialized(root, config_file)
    if _m25_successor_configured_on_any_surface(root, config):
        return _check_m25_materialized(root, config_file)
    if _m24_successor_configured_on_any_surface(root, config):
        return _check_m24_materialized(root, config_file)
    if _m23_successor_configured_on_any_surface(root, config):
        return _check_m23_materialized(root, config_file)
    if _m22_successor_configured_on_any_surface(root, config):
        return _check_m22_materialized(root, config_file)
    if _m21_successor_configured(config):
        return _check_m21_materialized(root, config_file)
    if _m20_successor_configured(config):
        return _check_m20_materialized(root, config_file)
    if _m19_successor_configured(config):
        return _check_m19_materialized(root, config_file)
    if _m18_successor_configured(config):
        return _check_m18_materialized(root, config_file)
    if _m17_successor_configured(config):
        return _check_m17_materialized(root, config_file)
    if _m16_successor_configured(config):
        return _check_m16_materialized(root, config_file)
    if _m15_successor_configured(config):
        return _check_m15_materialized(root, config_file)
    if _m14_successor_configured(config):
        return _check_m14_materialized(root, config_file)
    if _m13_successor_configured(config):
        return _check_m13_materialized(root, config_file)
    if _m12_successor_configured(config):
        return _check_m12_materialized(root, config_file)
    if _m11_successor_configured(config):
        return _check_m11_materialized(root, config_file)
    if _m10_successor_configured(config):
        return _check_m10_materialized(root, config_file)
    if _m9_successor_configured(config):
        return _check_m9_materialized(root, config_file)
    if _m8_successor_configured(config):
        return _check_m8_materialized(root, config_file)
    return _check_m7_materialized(root, config_file)


def _materialize_m7(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m7_source_repair_authority(population, config)
    target = (root / str(config["database_program"]["store_id"])).resolve()
    if (
        str(config["database_program"]["store_id"])
        != authority["target_store_id"]
        or int(config["database_program"].get("store_generation") or 0)
        != _M7_TARGET_GENERATION
        or str(config["quack_owner"].get("database_path") or "")
        != authority["target_store_id"]
        or str(config["quack_owner"].get("store_id") or "")
        != authority["target_store_id"]
    ):
        raise MaterializationError("scheduler M7 target/generation binding differs")
    if not target.is_relative_to(root):
        raise MaterializationError("M7 target escapes the repository root")
    validation_digest = _m7_validation_digest(root, population)
    m5 = _verify_prior_store(root, config, population)
    m6 = _verify_frozen_m6_authority(root, config, population)
    prior_path = Path(m6["database_path"])
    if target.exists():
        verified = _verify_m7_store(
            target,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m7_migration_receipt(
            root,
            target,
            population,
            config,
            verified,
            validation_digest,
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(target),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "m5_authority": m5,
            "prior_authority": m6,
            "receipt": receipt,
            **verified,
        }

    _assert_fresh_successor_operational_state(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(target.parent.glob(target.name + ".installing.*"))
    if preserved_stages:
        raise MaterializationError(
            "preserved M7 staging attempt requires inspection: "
            + ", ".join(str(item) for item in preserved_stages)
        )
    stage = target.with_name(
        target.name
        + f".installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    shutil.copy2(prior_path, stage)
    if _store_sha256(stage) != authority["prior_control_store_sha256"]:
        raise MaterializationError("staged M6 copy differs before M7 migration")
    before_semantic_authority = _semantic_authority_digest(stage)
    before_frozen_base_authority = _frozen_base_authority_digest(stage)
    if (
        before_semantic_authority
        != authority["prior_semantic_authority_digest"]
        or before_frozen_base_authority
        != authority["prior_frozen_base_authority_digest"]
    ):
        raise MaterializationError("staged M6 authority digest differs")

    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )
    source = DatabaseTaskSource(
        stage,
        install_schema=False,
        repository_tree_id=str(population["repository_tree_id"]),
        plan_root_cid=str(population["plan_root_cid"]),
        owner_id="sawm-r2-source-migrator",
    )
    try:
        operator = source.get_task("SAWM-000")
        if operator is None or operator.status != "completed" or operator.revision != 2:
            raise MaterializationError("M7 preserved operator completion differs")
        migration_body = _m7_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_delta = _m7_migration_plan_delta(population, config)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M7_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M7_SUPERSESSION_MODE,
            },
            delta=plan_delta,
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_source_migration",
            digest=migration_digest,
            body=migration_body,
        )
        unchanged = source.get_task(operator.task_cid)
        if unchanged is None or unchanged.status != "completed" or unchanged.revision != 2:
            raise MaterializationError("M7 migration changed operator task state")
    finally:
        source.close()
    after_semantic_authority = _semantic_authority_digest(stage)
    after_frozen_base_authority = _frozen_base_authority_digest(stage)
    if (
        after_semantic_authority != before_semantic_authority
        or after_frozen_base_authority != before_frozen_base_authority
    ):
        raise MaterializationError(
            "M7 source-only migration changed frozen authority"
        )
    verified = _verify_m7_store(
        stage,
        population,
        config,
        validation_digest,
    )
    if (
        int(verified["event_watermark"]) != _M7_TARGET_EVENT_WATERMARK
        or verified["projection_cid"] != _M7_EXPECTED_PROJECTION_CID
    ):
        raise MaterializationError("M7 emitted an unexpected event/projection suffix")
    if _store_sha256(prior_path) != authority["prior_control_store_sha256"]:
        raise MaterializationError("M7 migration changed frozen M6 authority")

    # Close the source-tree TOCTOU window before making the staged authority
    # visible.  The staged database is intentionally retained for inspection
    # if this check fails.
    _assert_committed_clean_source(root, population)
    _assert_m7_source_delta(root, population, authority)
    with stage.open("rb") as staged_file:
        os.fsync(staged_file.fileno())

    lock = target.with_name(target.name + ".publish.lock")
    fd = None
    directory_fd = None
    try:
        fd = os.open(lock, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        directory_fd = os.open(target.parent, os.O_RDONLY)
        if target.exists():
            raise MigrationRequired(
                "another writer published M7; inspect it append-only"
            )
        os.link(stage, target)
        os.fsync(directory_fd)
        os.unlink(stage)
        os.fsync(directory_fd)
    finally:
        if directory_fd is not None:
            os.close(directory_fd)
        if fd is not None:
            os.close(fd)
            lock.unlink(missing_ok=True)
    receipt = _ensure_m7_migration_receipt(
        root,
        target,
        population,
        config,
        verified,
        validation_digest,
    )
    history = _ducklake_projection(
        root,
        config,
        {
            "program_definition_cid": population["program_definition_cid"],
            "projection_cid": verified["projection_cid"],
        },
    )
    report = {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only",
        "migration_required": False,
        "database_path": str(target),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "m5_authority": m5,
        "prior_authority": m6,
        "plan_migration_event_id": plan_receipt.event_id,
        "migration_evidence_event_id": evidence.event_id,
        "migration_digest": migration_digest,
        "semantic_authority_digest_before": before_semantic_authority,
        "semantic_authority_digest_after": after_semantic_authority,
        "frozen_base_authority_digest_before": before_frozen_base_authority,
        "frozen_base_authority_digest_after": after_frozen_base_authority,
        "ducklake_history": history,
        "receipt": receipt,
        **verified,
    }
    return report


def _stage_m11_store_pair(
    root: Path,
    stage_dir: Path,
    prior_control: Path,
    prior_coordination: Path,
    prior_coordination_wal: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Build M11 only in a private directory from exact M10 base/WAL bytes."""

    authority = _m11_live_provider_retry_authority(population, config)
    stage_control = stage_dir / "control.duckdb"
    stage_coordination = stage_dir / "control.coordination.duckdb"
    stage_coordination_wal = stage_coordination.with_name(
        stage_coordination.name + ".wal"
    )
    stage_prior_control = stage_dir / "prior-control.duckdb"
    stage_prior_coordination = stage_dir / "prior-control.coordination.duckdb"
    stage_prior_coordination_wal = stage_prior_coordination.with_name(
        stage_prior_coordination.name + ".wal"
    )
    for source_path, target_path in (
        (prior_control, stage_control),
        (prior_coordination, stage_coordination),
        (prior_coordination_wal, stage_coordination_wal),
        (prior_control, stage_prior_control),
        (prior_coordination, stage_prior_coordination),
        (prior_coordination_wal, stage_prior_coordination_wal),
    ):
        shutil.copyfile(source_path, target_path)
    if (
        _store_sha256(stage_control) != authority["prior_control_store_sha256"]
        or stage_control.stat().st_size
        != int(authority["prior_control_store_size"])
        or _store_sha256(stage_coordination)
        != authority["prior_coordination_store_sha256"]
        or stage_coordination.stat().st_size
        != int(authority["prior_coordination_store_size"])
        or _store_sha256(stage_coordination_wal)
        != authority["prior_coordination_wal_sha256"]
        or stage_coordination_wal.stat().st_size
        != int(authority["prior_coordination_wal_size"])
        or _store_sha256(stage_prior_control)
        != authority["prior_control_store_sha256"]
        or _store_sha256(stage_prior_coordination)
        != authority["prior_coordination_store_sha256"]
        or _store_sha256(stage_prior_coordination_wal)
        != authority["prior_coordination_wal_sha256"]
    ):
        raise MaterializationError("staged M10 base/WAL copies differ")

    from ipfs_accelerate_py.agent_supervisor.merge.database_coordination import (
        DatabaseCoordinator,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources import (
        intent_repository as intent_repository_module,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    original_utc_iso = intent_repository_module._utc_iso

    def fixed_m11_utc_iso(_moment: Any = None) -> str:
        return _M11_CONTROL_RECORDED_AT

    intent_repository_module._utc_iso = fixed_m11_utc_iso
    source: Any | None = None
    clock_interference = False
    try:
        source = DatabaseTaskSource(
            stage_control,
            install_schema=False,
            repository_tree_id=str(population["repository_tree_id"]),
            plan_root_cid=str(population["plan_root_cid"]),
            owner_id="sawm-r2-provider-retry-migrator",
        )
        operator = source.get_task("SAWM-000")
        candidate = source.get_task("SAWM-001")
        if (
            operator is None
            or operator.status != "completed"
            or operator.revision != 2
            or candidate is None
            or candidate.status != "blocked"
            or candidate.revision != 12
            or dict(candidate.body).get("completion_receipt")
            != _M10_LIVE_FAILURE_RECEIPT
        ):
            raise MaterializationError("staged M10 task authority differs")
        migration_body = _m11_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M11_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M11_SUPERSESSION_MODE,
            },
            delta=_m11_migration_plan_delta(population, config),
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_source_migration",
            digest=migration_digest,
            body=migration_body,
        )
        task_cas = source.compare_and_set_status(
            _M10_LIVE_FAILURE_RECEIPT["task_cid"],
            12,
            "retrying",
            _m11_task_rearm_receipt(),
        )
        if (
            task_cas.changed is not True
            or task_cas.previous_status != "blocked"
            or task_cas.revision != 13
            or task_cas.event_cursor != _M11_TARGET_EVENT_WATERMARK
        ):
            raise MaterializationError("M11 operator task rearm CAS differs")
    finally:
        try:
            if source is not None:
                source.close()
        finally:
            clock_interference = (
                intent_repository_module._utc_iso is not fixed_m11_utc_iso
            )
            intent_repository_module._utc_iso = original_utc_iso
    if clock_interference or intent_repository_module._utc_iso is not original_utc_iso:
        raise MaterializationError("M11 deterministic control clock binding drifted")

    coordinator = DatabaseCoordinator(stage_coordination).open()
    try:
        coordination_rearm = coordinator.rearm_failed_task(
            failure_receipt=_M10_LIVE_FAILURE_RECEIPT,
            control_task_observation=task_cas.to_dict(),
            now_ms=_M11_COORDINATION_REARM_OBSERVED_AT_MS,
        )
    finally:
        coordinator.close()
    if (
        coordination_rearm.get("ready") is not True
        or coordination_rearm.get("replayed") is not False
        or not str(coordination_rearm.get("rearm_id") or "")
    ):
        raise MaterializationError("M11 coordinator rearm result differs")
    # The copied predecessor WAL is input evidence, but the M11 target is
    # published as one self-contained base file.  Checkpoint only the staged
    # target; the original and staged predecessor base/WAL remain untouched.
    import duckdb

    checkpoint = duckdb.connect(str(stage_coordination))
    try:
        checkpoint.execute("CHECKPOINT")
    finally:
        checkpoint.close()
    if os.path.lexists(stage_control.with_name(stage_control.name + ".wal")):
        raise MaterializationError("M11 control mutation retained a WAL")
    if os.path.lexists(stage_coordination_wal):
        raise MaterializationError("M11 coordination mutation retained a WAL")

    verified = _verify_m11_store_pair_copy(
        stage_control,
        stage_coordination,
        stage_prior_control,
        stage_prior_coordination,
        population,
        config,
        validation_digest,
    )
    if (
        verified["projection_cid"] != authority["target_projection_cid"]
        or verified["coordination_projection_digest"]
        != authority["target_coordination_projection_digest"]
        or int(verified["coordination_event_count"])
        != int(authority["target_coordination_event_count"])
    ):
        raise MaterializationError("M11 staged pair has unexpected projections")
    return {
        "stage_control": stage_control,
        "stage_coordination": stage_coordination,
        "stage_prior_control": stage_prior_control,
        "stage_prior_coordination": stage_prior_coordination,
        "stage_prior_coordination_wal": stage_prior_coordination_wal,
        "plan_receipt": plan_receipt,
        "evidence": evidence,
        "task_cas": task_cas,
        "coordination_rearm": coordination_rearm,
        "migration_digest": migration_digest,
        "verified": verified,
    }


def _stage_m12_store_pair(
    root: Path,
    stage_dir: Path,
    prior_control: Path,
    prior_coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Build M12 only in a private directory from exact stopped-M11 bases."""

    authority = _m12_declared_output_retry_authority(population, config)
    stage_control = stage_dir / "control.duckdb"
    stage_coordination = stage_dir / "control.coordination.duckdb"
    stage_prior_control = stage_dir / "prior-control.duckdb"
    stage_prior_coordination = stage_dir / "prior-control.coordination.duckdb"
    for source_path, target_path in (
        (prior_control, stage_control),
        (prior_coordination, stage_coordination),
        (prior_control, stage_prior_control),
        (prior_coordination, stage_prior_coordination),
    ):
        shutil.copyfile(source_path, target_path)
    if (
        _store_sha256(stage_control) != authority["prior_control_store_sha256"]
        or stage_control.stat().st_size
        != int(authority["prior_control_store_size"])
        or _store_sha256(stage_coordination)
        != authority["prior_coordination_store_sha256"]
        or stage_coordination.stat().st_size
        != int(authority["prior_coordination_store_size"])
        or _store_sha256(stage_prior_control)
        != authority["prior_control_store_sha256"]
        or _store_sha256(stage_prior_coordination)
        != authority["prior_coordination_store_sha256"]
        or any(
            os.path.lexists(path)
            for path in (
                stage_control.with_name(stage_control.name + ".wal"),
                stage_coordination.with_name(stage_coordination.name + ".wal"),
                stage_prior_control.with_name(stage_prior_control.name + ".wal"),
                stage_prior_coordination.with_name(
                    stage_prior_coordination.name + ".wal"
                ),
            )
        )
    ):
        raise MaterializationError("staged M11 base copies differ")

    from ipfs_accelerate_py.agent_supervisor.merge.database_coordination import (
        DatabaseCoordinator,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources import (
        intent_repository as intent_repository_module,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    original_utc_iso = intent_repository_module._utc_iso

    def fixed_m12_utc_iso(_moment: Any = None) -> str:
        return _M12_CONTROL_RECORDED_AT

    intent_repository_module._utc_iso = fixed_m12_utc_iso
    source: Any | None = None
    clock_interference = False
    try:
        source = DatabaseTaskSource(
            stage_control,
            install_schema=False,
            repository_tree_id=str(population["repository_tree_id"]),
            plan_root_cid=str(population["plan_root_cid"]),
            owner_id="sawm-r2-declared-path-migrator",
        )
        operator = source.get_task("SAWM-000")
        candidate = source.get_task("SAWM-001")
        if (
            operator is None
            or operator.status != "completed"
            or operator.revision != 2
            or candidate is None
            or candidate.status != "blocked"
            or candidate.revision != 15
            or dict(candidate.body).get("completion_receipt")
            != _M12_LIVE_FAILURE_RECEIPT
        ):
            raise MaterializationError("staged M11 task authority differs")
        migration_body = _m12_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M12_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M12_SUPERSESSION_MODE,
            },
            delta=_m12_migration_plan_delta(population, config),
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_source_migration",
            digest=migration_digest,
            body=migration_body,
        )
        task_cas = source.compare_and_set_status(
            _M12_LIVE_FAILURE_RECEIPT["task_cid"],
            15,
            "retrying",
            _m12_task_rearm_receipt(),
        )
        if (
            task_cas.changed is not True
            or task_cas.previous_status != "blocked"
            or task_cas.revision != 16
            or task_cas.event_cursor != _M12_TARGET_EVENT_WATERMARK
        ):
            raise MaterializationError("M12 operator task rearm CAS differs")
    finally:
        try:
            if source is not None:
                source.close()
        finally:
            clock_interference = (
                intent_repository_module._utc_iso is not fixed_m12_utc_iso
            )
            intent_repository_module._utc_iso = original_utc_iso
    if clock_interference or intent_repository_module._utc_iso is not original_utc_iso:
        raise MaterializationError("M12 deterministic control clock binding drifted")

    coordinator = DatabaseCoordinator(stage_coordination).open()
    try:
        coordination_rearm = coordinator.rearm_failed_task(
            failure_receipt=_M12_LIVE_FAILURE_RECEIPT,
            control_task_observation=task_cas.to_dict(),
            now_ms=_M12_COORDINATION_REARM_OBSERVED_AT_MS,
        )
    finally:
        coordinator.close()
    if (
        coordination_rearm.get("ready") is not True
        or coordination_rearm.get("replayed") is not False
        or not str(coordination_rearm.get("rearm_id") or "")
    ):
        raise MaterializationError("M12 coordinator rearm result differs")
    import duckdb

    checkpoint = duckdb.connect(str(stage_coordination))
    try:
        checkpoint.execute("CHECKPOINT")
    finally:
        checkpoint.close()
    if any(
        os.path.lexists(path)
        for path in (
            stage_control.with_name(stage_control.name + ".wal"),
            stage_coordination.with_name(stage_coordination.name + ".wal"),
        )
    ):
        raise MaterializationError("M12 mutation retained a WAL")

    verified = _verify_m12_store_pair_copy(
        stage_control,
        stage_coordination,
        stage_prior_control,
        stage_prior_coordination,
        population,
        config,
        validation_digest,
    )
    if (
        verified["projection_cid"] != authority["target_projection_cid"]
        or verified["coordination_projection_digest"]
        != authority["target_coordination_projection_digest"]
        or int(verified["coordination_event_count"])
        != int(authority["target_coordination_event_count"])
    ):
        raise MaterializationError("M12 staged pair has unexpected projections")
    return {
        "stage_control": stage_control,
        "stage_coordination": stage_coordination,
        "stage_prior_control": stage_prior_control,
        "stage_prior_coordination": stage_prior_coordination,
        "plan_receipt": plan_receipt,
        "evidence": evidence,
        "task_cas": task_cas,
        "coordination_rearm": coordination_rearm,
        "migration_digest": migration_digest,
        "verified": verified,
    }


def _materialize_m12(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append the declared-output repair/rearm and publish M12 atomically."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m12_declared_output_retry_authority(population, config)
    _assert_m12_source_delta(root, population, authority)
    control, coordination = _m12_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination, prior = (
        _assert_m12_prior_publication_anchor(root, authority, population)
    )

    control_present = os.path.lexists(control)
    coordination_present = os.path.lexists(coordination)
    receipt_present = os.path.lexists(receipt_path)
    if control_present != coordination_present:
        raise MigrationRequired(
            "M12 has a partial published store pair without a final marker"
        )
    if receipt_present and not control_present:
        raise MigrationRequired("M12 has an orphaned pair commit marker")
    if control_present:
        verified = _verify_m12_store_pair(
            root,
            control,
            coordination,
            prior_control,
            prior_coordination,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m12_migration_receipt(
            root,
            control,
            coordination,
            population,
            config,
            verified,
            validation_digest,
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(control),
            "coordination_path": str(coordination),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "prior_authority": prior,
            "receipt": receipt,
            **verified,
        }

    prohibited = (
        control,
        coordination,
        receipt_path,
        control.with_name(control.name + ".wal"),
        coordination.with_name(coordination.name + ".wal"),
        control.with_name("control.execution.duckdb"),
        control.with_name("control.execution.duckdb.wal"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name("control.read-replica.duckdb.wal"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "quack-owner",
    )
    present = [str(path) for path in prohibited if os.path.lexists(path)]
    if present:
        raise MaterializationError(
            "M12 successor operational authority is not fresh: "
            + json.dumps(present, sort_keys=True, separators=(",", ":"))
        )
    control.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(control.parent.glob(".m12-installing.*"))
    pending_receipts = sorted(
        control.parent.glob(f".{receipt_path.name}.*.tmp")
    )
    if preserved_stages or pending_receipts:
        raise MaterializationError(
            "preserved M12 staging/receipt attempt requires inspection: "
            + ", ".join(
                str(item) for item in (*preserved_stages, *pending_receipts)
            )
        )
    stage_dir = control.parent / (
        f".m12-installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    os.mkdir(stage_dir, 0o700)
    staged = _stage_m12_store_pair(
        root,
        stage_dir,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    stage_control = staged["stage_control"]
    stage_coordination = staged["stage_coordination"]
    staged_verified = staged["verified"]

    _assert_committed_clean_source(root, population)
    _assert_m12_source_delta(root, population, authority)
    _assert_m12_prior_publication_anchor(root, authority, population)
    for stage_path in (stage_control, stage_coordination):
        with stage_path.open("rb") as staged_file:
            os.fsync(staged_file.fileno())

    bundle_lock = control.parent / ".m12-store-pair.publish.lock"
    descriptor = os.open(
        bundle_lock,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    created: list[tuple[Path, int, int]] = []
    stage_aliases_removed = False
    committed = False
    receipt: dict[str, Any] | None = None
    published_verified: dict[str, Any] | None = None
    try:
        lock_stat = os.fstat(descriptor)
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
            raise MaterializationError("M12 bundle lock is not a regular file")
        deadline = time.monotonic() + 10.0
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise MaterializationError(
                        "timed out acquiring the M12 pair publication lock"
                    ) from exc
                time.sleep(0.02)
        if any(
            os.path.lexists(path)
            for path in (control, coordination, receipt_path)
        ):
            raise MigrationRequired(
                "another writer published part of the M12 store pair"
            )
        _assert_committed_clean_source(root, population)
        _assert_m12_source_delta(root, population, authority)
        _assert_m12_prior_publication_anchor(root, authority, population)
        directory = os.open(
            control.parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            stage_control_stat = os.lstat(stage_control)
            os.link(stage_control, control, follow_symlinks=False)
            created.append(
                (control, stage_control_stat.st_dev, stage_control_stat.st_ino)
            )
            os.fsync(directory)
            stage_coordination_stat = os.lstat(stage_coordination)
            os.link(stage_coordination, coordination, follow_symlinks=False)
            created.append(
                (
                    coordination,
                    stage_coordination_stat.st_dev,
                    stage_coordination_stat.st_ino,
                )
            )
            os.fsync(directory)
            _assert_committed_clean_source(root, population)
            _assert_m12_source_delta(root, population, authority)
            _assert_m12_prior_publication_anchor(root, authority, population)

            removable_names = {
                "control.duckdb",
                "control.coordination.duckdb",
                "prior-control.duckdb",
                "prior-control.coordination.duckdb",
                ".control.duckdb.intent.lock",
                ".control.duckdb.lock",
                ".control.coordination.duckdb.lock",
            }
            stage_entries = tuple(stage_dir.iterdir())
            unexpected = sorted(
                path.name
                for path in stage_entries
                if path.name not in removable_names
            )
            if unexpected:
                raise MaterializationError(
                    "M12 staging directory has unexpected leaves: "
                    + ", ".join(unexpected)
                )
            for path in stage_entries:
                leaf_stat = os.lstat(path)
                if not stat.S_ISREG(leaf_stat.st_mode):
                    raise MaterializationError(
                        "M12 staging leaf changed before alias removal"
                    )
            for path in stage_entries:
                os.unlink(path)
            stage_dir.rmdir()
            os.fsync(directory)
            stage_aliases_removed = True
            if any(
                os.path.lexists(path)
                for path in (
                    control.with_name("control.execution.duckdb"),
                    control.with_name("control.execution.duckdb.wal"),
                    control.with_name("control.read-replica.duckdb"),
                    control.with_name("control.read-replica.duckdb.wal"),
                    control.with_name(control.name + ".wal"),
                    coordination.with_name(coordination.name + ".wal"),
                )
            ):
                raise MigrationRequired(
                    "M12 mutable sidecar appeared before pair admission"
                )
            published_verified = _verify_m12_store_pair(
                root,
                control,
                coordination,
                prior_control,
                prior_coordination,
                population,
                config,
                validation_digest,
            )
            for key in (
                "control_store_sha256",
                "coordination_store_sha256",
                "migration_evidence_id",
                "task_rearm_event_id",
                "coordination_rearm_event_id",
                "coordination_projection_digest",
            ):
                if published_verified.get(key) != staged_verified.get(key):
                    raise MaterializationError(
                        f"published M12 pair differs from staging: {key}"
                    )
            receipt = _ensure_m12_migration_receipt(
                root,
                control,
                coordination,
                population,
                config,
                published_verified,
                validation_digest,
                pair_lock_held=True,
            )
            committed = True
        finally:
            os.close(directory)
    except Exception:
        if (
            not committed
            and not stage_aliases_removed
            and not os.path.lexists(receipt_path)
        ):
            rollback_directory = os.open(
                control.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                for published, expected_device, expected_inode in reversed(created):
                    if not os.path.lexists(published):
                        continue
                    published_stat = os.lstat(published)
                    if (
                        published_stat.st_dev == expected_device
                        and published_stat.st_ino == expected_inode
                    ):
                        os.unlink(published)
                os.fsync(rollback_directory)
            finally:
                os.close(rollback_directory)
        raise
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)

    if not committed or receipt is None or published_verified is None:
        raise MaterializationError("M12 pair publication lacked its final marker")
    if not stage_aliases_removed:
        raise MaterializationError("M12 receipt preceded staging-alias removal")
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only_control_and_coordination",
        "migration_required": False,
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "plan_migration_event_id": staged["plan_receipt"].event_id,
        "migration_evidence_event_id": staged["evidence"].event_id,
        "task_rearm_event_id": published_verified["task_rearm_event_id"],
        "coordination_rearm_event_id": published_verified[
            "coordination_rearm_event_id"
        ],
        "migration_digest": staged["migration_digest"],
        "stage_cleanup_complete": True,
        "receipt": receipt,
        **published_verified,
    }


def _materialize_m11(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append the bounded provider repair/rearm and publish M11 atomically."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m11_live_provider_retry_authority(population, config)
    _assert_m11_source_delta(root, population, authority)
    control, coordination = _m11_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination, prior_coordination_wal, prior = (
        _assert_m11_prior_publication_anchor(root, authority, population)
    )

    control_present = os.path.lexists(control)
    coordination_present = os.path.lexists(coordination)
    receipt_present = os.path.lexists(receipt_path)
    if control_present != coordination_present:
        raise MigrationRequired(
            "M11 has a partial published store pair without a final marker"
        )
    if receipt_present and not control_present:
        raise MigrationRequired("M11 has an orphaned pair commit marker")
    if control_present:
        verified = _verify_m11_store_pair(
            root,
            control,
            coordination,
            prior_control,
            prior_coordination,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m11_migration_receipt(
            root,
            control,
            coordination,
            population,
            config,
            verified,
            validation_digest,
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(control),
            "coordination_path": str(coordination),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "prior_authority": prior,
            "receipt": receipt,
            **verified,
        }

    prohibited = (
        control,
        coordination,
        receipt_path,
        control.with_name(control.name + ".wal"),
        coordination.with_name(coordination.name + ".wal"),
        control.with_name("control.execution.duckdb"),
        control.with_name("control.execution.duckdb.wal"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "quack-owner",
    )
    present = [str(path) for path in prohibited if os.path.lexists(path)]
    if present:
        raise MaterializationError(
            "M11 successor operational authority is not fresh: "
            + json.dumps(present, sort_keys=True, separators=(",", ":"))
        )
    control.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(control.parent.glob(".m11-installing.*"))
    pending_receipts = sorted(
        control.parent.glob(f".{receipt_path.name}.*.tmp")
    )
    if preserved_stages or pending_receipts:
        raise MaterializationError(
            "preserved M11 staging/receipt attempt requires inspection: "
            + ", ".join(
                str(item) for item in (*preserved_stages, *pending_receipts)
            )
        )
    stage_dir = control.parent / (
        f".m11-installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    os.mkdir(stage_dir, 0o700)
    staged = _stage_m11_store_pair(
        root,
        stage_dir,
        prior_control,
        prior_coordination,
        prior_coordination_wal,
        population,
        config,
        validation_digest,
    )
    stage_control = staged["stage_control"]
    stage_coordination = staged["stage_coordination"]
    staged_verified = staged["verified"]

    _assert_committed_clean_source(root, population)
    _assert_m11_source_delta(root, population, authority)
    _assert_m11_prior_publication_anchor(root, authority, population)
    for stage_path in (stage_control, stage_coordination):
        with stage_path.open("rb") as staged_file:
            os.fsync(staged_file.fileno())

    bundle_lock = control.parent / ".m11-store-pair.publish.lock"
    descriptor = os.open(
        bundle_lock,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    created: list[tuple[Path, int, int]] = []
    stage_aliases_removed = False
    committed = False
    receipt: dict[str, Any] | None = None
    published_verified: dict[str, Any] | None = None
    try:
        lock_stat = os.fstat(descriptor)
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
            raise MaterializationError("M11 bundle lock is not a regular file")
        deadline = time.monotonic() + 10.0
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise MaterializationError(
                        "timed out acquiring the M11 pair publication lock"
                    ) from exc
                time.sleep(0.02)
        if any(
            os.path.lexists(path)
            for path in (control, coordination, receipt_path)
        ):
            raise MigrationRequired(
                "another writer published part of the M11 store pair"
            )
        _assert_committed_clean_source(root, population)
        _assert_m11_source_delta(root, population, authority)
        _assert_m11_prior_publication_anchor(root, authority, population)
        directory = os.open(
            control.parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            stage_control_stat = os.lstat(stage_control)
            os.link(stage_control, control, follow_symlinks=False)
            created.append(
                (control, stage_control_stat.st_dev, stage_control_stat.st_ino)
            )
            os.fsync(directory)
            stage_coordination_stat = os.lstat(stage_coordination)
            os.link(stage_coordination, coordination, follow_symlinks=False)
            created.append(
                (
                    coordination,
                    stage_coordination_stat.st_dev,
                    stage_coordination_stat.st_ino,
                )
            )
            os.fsync(directory)
            _assert_committed_clean_source(root, population)
            _assert_m11_source_delta(root, population, authority)
            _assert_m11_prior_publication_anchor(root, authority, population)

            removable_names = {
                "control.duckdb",
                "control.coordination.duckdb",
                "prior-control.duckdb",
                "prior-control.coordination.duckdb",
                "prior-control.coordination.duckdb.wal",
                ".control.duckdb.intent.lock",
                ".control.duckdb.lock",
                ".control.coordination.duckdb.lock",
            }
            stage_entries = tuple(stage_dir.iterdir())
            unexpected = sorted(
                path.name
                for path in stage_entries
                if path.name not in removable_names
            )
            if unexpected:
                raise MaterializationError(
                    "M11 staging directory has unexpected leaves: "
                    + ", ".join(unexpected)
                )
            for path in stage_entries:
                leaf_stat = os.lstat(path)
                if not stat.S_ISREG(leaf_stat.st_mode):
                    raise MaterializationError(
                        "M11 staging leaf changed before alias removal"
                    )
            for path in stage_entries:
                os.unlink(path)
            stage_dir.rmdir()
            os.fsync(directory)
            stage_aliases_removed = True
            if any(
                os.path.lexists(path)
                for path in (
                    control.with_name("control.execution.duckdb"),
                    control.with_name("control.execution.duckdb.wal"),
                    control.with_name("control.read-replica.duckdb"),
                    control.with_name(control.name + ".wal"),
                    coordination.with_name(coordination.name + ".wal"),
                )
            ):
                raise MigrationRequired(
                    "M11 mutable sidecar appeared before pair admission"
                )
            published_verified = _verify_m11_store_pair(
                root,
                control,
                coordination,
                prior_control,
                prior_coordination,
                population,
                config,
                validation_digest,
            )
            for key in (
                "control_store_sha256",
                "coordination_store_sha256",
                "migration_evidence_id",
                "task_rearm_event_id",
                "coordination_rearm_event_id",
                "coordination_projection_digest",
            ):
                if published_verified.get(key) != staged_verified.get(key):
                    raise MaterializationError(
                        f"published M11 pair differs from staging: {key}"
                    )
            receipt = _ensure_m11_migration_receipt(
                root,
                control,
                coordination,
                population,
                config,
                published_verified,
                validation_digest,
                pair_lock_held=True,
            )
            committed = True
        finally:
            os.close(directory)
    except Exception:
        if (
            not committed
            and not stage_aliases_removed
            and not os.path.lexists(receipt_path)
        ):
            rollback_directory = os.open(
                control.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                for published, expected_device, expected_inode in reversed(created):
                    if not os.path.lexists(published):
                        continue
                    published_stat = os.lstat(published)
                    if (
                        published_stat.st_dev == expected_device
                        and published_stat.st_ino == expected_inode
                    ):
                        os.unlink(published)
                os.fsync(rollback_directory)
            finally:
                os.close(rollback_directory)
        raise
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)

    if not committed or receipt is None or published_verified is None:
        raise MaterializationError("M11 pair publication lacked its final marker")
    if not stage_aliases_removed:
        raise MaterializationError("M11 receipt preceded staging-alias removal")
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only_control_and_coordination",
        "migration_required": False,
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "plan_migration_event_id": staged["plan_receipt"].event_id,
        "migration_evidence_event_id": staged["evidence"].event_id,
        "task_rearm_event_id": published_verified["task_rearm_event_id"],
        "coordination_rearm_event_id": published_verified[
            "coordination_rearm_event_id"
        ],
        "migration_digest": staged["migration_digest"],
        "stage_cleanup_complete": True,
        "receipt": receipt,
        **published_verified,
    }


def _materialize_m10(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append source evidence and publish M10's unchanged-coordinator pair."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m10_live_projection_authority(population, config)
    _assert_m10_source_delta(root, population, authority)
    control, coordination = _m10_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination = _assert_m10_prior_publication_anchor(
        root,
        authority,
    )
    prior = _verify_frozen_m9_live_authority(root, authority, population)

    control_present = os.path.lexists(control)
    coordination_present = os.path.lexists(coordination)
    receipt_present = os.path.lexists(receipt_path)
    if control_present != coordination_present:
        raise MigrationRequired(
            "M10 has a partial published store pair without a final marker"
        )
    if receipt_present and not control_present:
        raise MigrationRequired("M10 has an orphaned pair commit marker")
    if control_present:
        verified = _verify_m10_store_pair(
            root,
            control,
            coordination,
            prior_control,
            prior_coordination,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m10_migration_receipt(
            root,
            control,
            coordination,
            population,
            config,
            verified,
            validation_digest,
        )
        history = _ducklake_projection(
            root,
            config,
            {
                "program_definition_cid": population["program_definition_cid"],
                "projection_cid": verified["projection_cid"],
            },
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(control),
            "coordination_path": str(coordination),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "prior_authority": prior,
            "receipt": receipt,
            "ducklake_history": history,
            **verified,
        }

    prohibited = (
        control,
        coordination,
        receipt_path,
        control.with_name("control.execution.duckdb"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "quack-owner",
    )
    present = [str(path) for path in prohibited if os.path.lexists(path)]
    if present:
        raise MaterializationError(
            "M10 successor operational authority is not fresh: "
            + json.dumps(present, sort_keys=True, separators=(",", ":"))
        )
    control.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(control.parent.glob(".m10-installing.*"))
    if preserved_stages:
        raise MaterializationError(
            "preserved M10 staging attempt requires inspection: "
            + ", ".join(str(item) for item in preserved_stages)
        )
    stage_dir = control.parent / (
        f".m10-installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    os.mkdir(stage_dir, 0o700)
    stage_control = stage_dir / "control.duckdb"
    stage_coordination = stage_dir / "control.coordination.duckdb"
    shutil.copy2(prior_control, stage_control)
    shutil.copy2(prior_coordination, stage_coordination)
    if (
        _store_sha256(stage_control) != authority["prior_control_store_sha256"]
        or stage_control.stat().st_size
        != int(authority["prior_control_store_size"])
        or _store_sha256(stage_coordination)
        != authority["prior_coordination_store_sha256"]
        or stage_coordination.stat().st_size
        != int(authority["prior_coordination_store_size"])
    ):
        raise MaterializationError("staged M9 pair differs before M10 migration")
    before_semantic = _semantic_authority_digest(stage_control)
    before_frozen = _frozen_base_authority_digest(stage_control)
    before_coordination_sha256 = _store_sha256(stage_coordination)
    if (
        before_semantic != authority["prior_semantic_authority_digest"]
        or before_frozen != authority["prior_frozen_base_authority_digest"]
    ):
        raise MaterializationError("staged M9 frozen authority digest differs")

    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    source = DatabaseTaskSource(
        stage_control,
        install_schema=False,
        repository_tree_id=str(population["repository_tree_id"]),
        plan_root_cid=str(population["plan_root_cid"]),
        owner_id="sawm-r2-live-projection-migrator",
    )
    try:
        operator = source.get_task("SAWM-000")
        candidate = source.get_task("SAWM-001")
        if (
            operator is None
            or operator.status != "completed"
            or operator.revision != 2
            or candidate is None
            or candidate.status != "retrying"
            or candidate.revision != 10
            or dict(candidate.body).get("completion_receipt")
            != _m9_task_rearm_receipt()
        ):
            raise MaterializationError("staged M9 task authority differs")
        migration_body = _m10_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M10_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M10_SUPERSESSION_MODE,
            },
            delta=_m10_migration_plan_delta(population, config),
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_source_migration",
            digest=migration_digest,
            body=migration_body,
        )
        unchanged_operator = source.get_task("SAWM-000")
        unchanged_candidate = source.get_task("SAWM-001")
        if (
            unchanged_operator is None
            or unchanged_operator.status != "completed"
            or unchanged_operator.revision != 2
            or unchanged_candidate is None
            or unchanged_candidate.status != "retrying"
            or unchanged_candidate.revision != 10
            or dict(unchanged_candidate.body).get("completion_receipt")
            != _m9_task_rearm_receipt()
        ):
            raise MaterializationError("M10 source append changed task authority")
    finally:
        source.close()

    after_semantic = _semantic_authority_digest(stage_control)
    after_frozen = _frozen_base_authority_digest(stage_control)
    if (
        after_semantic != before_semantic
        or after_frozen != before_frozen
        or _store_sha256(stage_coordination) != before_coordination_sha256
    ):
        raise MaterializationError("M10 source append changed frozen authority")
    verified = _verify_m10_store_pair_copy(
        stage_control,
        stage_coordination,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    if (
        verified["projection_cid"] != _M10_EXPECTED_PROJECTION_CID
        or verified["coordination_projection_digest"]
        != _M9_COORDINATION_PROJECTION_DIGEST
        or verified["coordination_store_sha256"]
        != authority["prior_coordination_store_sha256"]
    ):
        raise MaterializationError("M10 staged pair has unexpected projections")
    _assert_m10_prior_publication_anchor(root, authority)
    _assert_committed_clean_source(root, population)
    _assert_m10_source_delta(root, population, authority)
    for stage in (stage_control, stage_coordination):
        with stage.open("rb") as staged_file:
            os.fsync(staged_file.fileno())

    bundle_lock = control.parent / ".m10-store-pair.publish.lock"
    descriptor = os.open(
        bundle_lock,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    created: list[tuple[Path, int, int]] = []
    stage_aliases_removed = False
    committed = False
    receipt: dict[str, Any] | None = None
    published_verified: dict[str, Any] | None = None
    try:
        lock_stat = os.fstat(descriptor)
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
            raise MaterializationError("M10 bundle lock is not a regular file")
        deadline = time.monotonic() + 10.0
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise MaterializationError(
                        "timed out acquiring the M10 pair publication lock"
                    ) from exc
                time.sleep(0.02)
        if any(
            os.path.lexists(path)
            for path in (control, coordination, receipt_path)
        ):
            raise MigrationRequired(
                "another writer published part of the M10 store pair"
            )
        _assert_committed_clean_source(root, population)
        _assert_m10_source_delta(root, population, authority)
        _assert_m10_prior_publication_anchor(root, authority)
        directory = os.open(
            control.parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            stage_control_stat = stage_control.stat(follow_symlinks=False)
            os.link(stage_control, control, follow_symlinks=False)
            created.append(
                (control, stage_control_stat.st_dev, stage_control_stat.st_ino)
            )
            os.fsync(directory)
            stage_coordination_stat = stage_coordination.stat(
                follow_symlinks=False
            )
            os.link(stage_coordination, coordination, follow_symlinks=False)
            created.append(
                (
                    coordination,
                    stage_coordination_stat.st_dev,
                    stage_coordination_stat.st_ino,
                )
            )
            os.fsync(directory)
            _assert_committed_clean_source(root, population)
            _assert_m10_source_delta(root, population, authority)
            _assert_m10_prior_publication_anchor(root, authority)
            for path in (
                stage_control,
                stage_coordination,
                stage_dir / ".control.duckdb.intent.lock",
                stage_dir / ".control.duckdb.lock",
                stage_dir / ".control.coordination.duckdb.lock",
            ):
                if not os.path.lexists(path):
                    continue
                leaf_stat = os.lstat(path)
                if not stat.S_ISREG(leaf_stat.st_mode):
                    raise MaterializationError(
                        "M10 staging leaf changed before alias removal"
                    )
                os.unlink(path)
            stage_dir.rmdir()
            os.fsync(directory)
            stage_aliases_removed = True
            if (
                os.path.lexists(control.with_name("control.execution.duckdb"))
                or os.path.lexists(
                    control.with_name("control.read-replica.duckdb")
                )
            ):
                raise MigrationRequired(
                    "M10 mutable sidecar appeared before pair admission"
                )
            published_verified = _verify_m10_store_pair(
                root,
                control,
                coordination,
                prior_control,
                prior_coordination,
                population,
                config,
                validation_digest,
            )
            if (
                published_verified["control_store_sha256"]
                != verified["control_store_sha256"]
                or published_verified["coordination_store_sha256"]
                != verified["coordination_store_sha256"]
                or published_verified["migration_evidence_id"]
                != verified["migration_evidence_id"]
            ):
                raise MaterializationError("published M10 pair differs from staging")
            receipt = _ensure_m10_migration_receipt(
                root,
                control,
                coordination,
                population,
                config,
                published_verified,
                validation_digest,
                pair_lock_held=True,
            )
            committed = True
            os.fsync(directory)
        finally:
            os.close(directory)
    except Exception:
        if (
            not committed
            and not stage_aliases_removed
            and not os.path.lexists(receipt_path)
        ):
            rollback_directory = os.open(
                control.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                for published, expected_device, expected_inode in reversed(created):
                    if not os.path.lexists(published):
                        continue
                    published_stat = published.stat(follow_symlinks=False)
                    if (
                        published_stat.st_dev == expected_device
                        and published_stat.st_ino == expected_inode
                    ):
                        os.unlink(published)
                os.fsync(rollback_directory)
            finally:
                os.close(rollback_directory)
        raise
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)

    if not committed or receipt is None or published_verified is None:
        raise MaterializationError("M10 pair publication lacked its final marker")
    if not stage_aliases_removed:
        raise MaterializationError("M10 receipt preceded staging-alias removal")
    history = _ducklake_projection(
        root,
        config,
        {
            "program_definition_cid": population["program_definition_cid"],
            "projection_cid": published_verified["projection_cid"],
        },
    )
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only_control_and_unchanged_coordination",
        "migration_required": False,
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "plan_migration_event_id": plan_receipt.event_id,
        "migration_evidence_event_id": evidence.event_id,
        "migration_digest": migration_digest,
        "stage_cleanup_complete": True,
        "ducklake_history": history,
        "receipt": receipt,
        **published_verified,
    }


def _materialize_m9(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append, rearm, and publish the M9 control/coordinator pair."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m9_live_recovery_authority(population, config)
    _assert_m9_source_delta(root, population, authority)
    control, coordination = _m9_target_paths(root, config, authority)
    receipt_path = control.parent / "migration-receipt.json"
    validation_digest = _m7_validation_digest(root, population)
    prior_control, prior_coordination = _assert_m9_prior_publication_anchor(
        root,
        authority,
    )
    prior = _verify_frozen_m8_live_authority(root, authority)

    control_present = os.path.lexists(control)
    coordination_present = os.path.lexists(coordination)
    receipt_present = os.path.lexists(receipt_path)
    if control_present != coordination_present:
        raise MigrationRequired(
            "M9 has a partial published store pair without a commit marker"
        )
    if receipt_present and not control_present:
        raise MigrationRequired("M9 has an orphaned pair commit marker")
    if control_present:
        verified = _verify_m9_store_pair(
            root,
            control,
            coordination,
            prior_control,
            prior_coordination,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m9_migration_receipt(
            root,
            control,
            coordination,
            population,
            config,
            verified,
            validation_digest,
        )
        history = _ducklake_projection(
            root,
            config,
            {
                "program_definition_cid": population["program_definition_cid"],
                "projection_cid": verified["projection_cid"],
            },
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(control),
            "coordination_path": str(coordination),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "prior_authority": prior,
            "receipt": receipt,
            "ducklake_history": history,
            **verified,
        }

    prohibited = (
        control,
        coordination,
        receipt_path,
        control.with_name("control.execution.duckdb"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "quack-owner",
    )
    present = [str(path) for path in prohibited if os.path.lexists(path)]
    if present:
        raise MaterializationError(
            "M9 successor operational authority is not fresh: "
            + json.dumps(present, sort_keys=True, separators=(",", ":"))
        )
    control.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(control.parent.glob(".m9-installing.*"))
    if preserved_stages:
        raise MaterializationError(
            "preserved M9 staging attempt requires inspection: "
            + ", ".join(str(item) for item in preserved_stages)
        )
    stage_dir = control.parent / (
        f".m9-installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    os.mkdir(stage_dir, 0o700)
    stage_control = stage_dir / "control.duckdb"
    stage_coordination = stage_dir / "control.coordination.duckdb"
    shutil.copy2(prior_control, stage_control)
    shutil.copy2(prior_coordination, stage_coordination)
    if (
        _store_sha256(stage_control) != authority["prior_control_store_sha256"]
        or stage_control.stat().st_size
        != int(authority["prior_control_store_size"])
        or _store_sha256(stage_coordination)
        != authority["prior_coordination_store_sha256"]
        or stage_coordination.stat().st_size
        != int(authority["prior_coordination_store_size"])
    ):
        raise MaterializationError("staged M8 store pair differs before M9 migration")

    from ipfs_accelerate_py.agent_supervisor.merge.database_coordination import (
        DatabaseCoordinator,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    source = DatabaseTaskSource(
        stage_control,
        install_schema=False,
        repository_tree_id=str(population["repository_tree_id"]),
        plan_root_cid=str(population["plan_root_cid"]),
        owner_id="sawm-r2-runtime-recovery-migrator",
    )
    try:
        operator = source.get_task("SAWM-000")
        candidate = source.get_task("SAWM-001")
        if (
            operator is None
            or operator.status != "completed"
            or operator.revision != 2
            or candidate is None
            or candidate.status != "blocked"
            or candidate.revision != 9
            or dict(candidate.body).get("completion_receipt")
            != _M8_LIVE_FAILURE_RECEIPT
        ):
            raise MaterializationError("staged M8 task authority differs")
        migration_body = _m9_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M9_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M9_SUPERSESSION_MODE,
            },
            delta=_m9_migration_plan_delta(population, config),
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_runtime_recovery",
            digest=migration_digest,
            body=migration_body,
        )
        task_cas = source.compare_and_set_status(
            _M8_LIVE_FAILURE_RECEIPT["task_cid"],
            9,
            "retrying",
            _m9_task_rearm_receipt(),
        )
        if (
            task_cas.changed is not True
            or task_cas.previous_status != "blocked"
            or task_cas.revision != 10
            or task_cas.event_cursor != _M9_TARGET_EVENT_WATERMARK
        ):
            raise MaterializationError("M9 operator task rearm CAS differs")
    finally:
        source.close()

    coordinator = DatabaseCoordinator(stage_coordination).open()
    try:
        coordination_rearm = coordinator.rearm_failed_task(
            failure_receipt=_M8_LIVE_FAILURE_RECEIPT,
            control_task_observation=task_cas.to_dict(),
            now_ms=_M9_COORDINATION_REARM_OBSERVED_AT_MS,
        )
    finally:
        coordinator.close()
    if (
        coordination_rearm.get("ready") is not True
        or coordination_rearm.get("replayed") is not False
        or coordination_rearm.get("rearm_id")
        != "baguqeerayovxeby66ijejx2upicgqg2kyil4bcf4larci52bau6av6qc5dga"
    ):
        raise MaterializationError("M9 coordinator rearm result differs")

    verified = _verify_m9_store_pair_copy(
        stage_control,
        stage_coordination,
        prior_control,
        prior_coordination,
        population,
        config,
        validation_digest,
    )
    if (
        verified["projection_cid"] != _M9_EXPECTED_PROJECTION_CID
        or verified["coordination_projection_digest"]
        != _M9_COORDINATION_PROJECTION_DIGEST
    ):
        raise MaterializationError("M9 staged pair has unexpected projections")
    _assert_m9_prior_publication_anchor(root, authority)
    _assert_committed_clean_source(root, population)
    _assert_m9_source_delta(root, population, authority)
    for stage in (stage_control, stage_coordination):
        with stage.open("rb") as staged_file:
            os.fsync(staged_file.fileno())

    bundle_lock = control.parent / ".m9-store-pair.publish.lock"
    descriptor = os.open(
        bundle_lock,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    created: list[tuple[Path, int, int]] = []
    stage_aliases_removed = False
    committed = False
    receipt: dict[str, Any] | None = None
    published_verified: dict[str, Any] | None = None
    try:
        lock_stat = os.fstat(descriptor)
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_nlink != 1:
            raise MaterializationError("M9 bundle lock is not a regular file")
        deadline = time.monotonic() + 10.0
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise MaterializationError(
                        "timed out acquiring the M9 pair publication lock"
                    ) from exc
                time.sleep(0.02)
        if any(
            os.path.lexists(path)
            for path in (control, coordination, receipt_path)
        ):
            raise MigrationRequired(
                "another writer published part of the M9 store pair"
            )
        _assert_committed_clean_source(root, population)
        _assert_m9_source_delta(root, population, authority)
        _assert_m9_prior_publication_anchor(root, authority)
        directory = os.open(
            control.parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            stage_control_stat = stage_control.stat(follow_symlinks=False)
            os.link(stage_control, control, follow_symlinks=False)
            created.append(
                (control, stage_control_stat.st_dev, stage_control_stat.st_ino)
            )
            os.fsync(directory)
            stage_coordination_stat = stage_coordination.stat(
                follow_symlinks=False
            )
            os.link(stage_coordination, coordination, follow_symlinks=False)
            created.append(
                (
                    coordination,
                    stage_coordination_stat.st_dev,
                    stage_coordination_stat.st_ino,
                )
            )
            os.fsync(directory)
            _assert_committed_clean_source(root, population)
            _assert_m9_source_delta(root, population, authority)
            _assert_m9_prior_publication_anchor(root, authority)
            # Remove every mutable staging alias before final verification and
            # before the receipt can become the durable pair commit marker.
            for path in (
                stage_control,
                stage_coordination,
                stage_dir / ".control.duckdb.intent.lock",
                stage_dir / ".control.duckdb.lock",
                stage_dir / ".control.coordination.duckdb.lock",
            ):
                if not os.path.lexists(path):
                    continue
                leaf_stat = os.lstat(path)
                if not stat.S_ISREG(leaf_stat.st_mode):
                    raise MaterializationError(
                        "M9 staging leaf changed before alias removal"
                    )
                os.unlink(path)
            stage_dir.rmdir()
            os.fsync(directory)
            stage_aliases_removed = True
            if os.path.lexists(control.with_name("control.execution.duckdb")):
                raise MigrationRequired(
                    "M9 execution sidecar appeared before pair admission"
                )
            published_verified = _verify_m9_store_pair(
                root,
                control,
                coordination,
                prior_control,
                prior_coordination,
                population,
                config,
                validation_digest,
            )
            if (
                published_verified["control_store_sha256"]
                != verified["control_store_sha256"]
                or published_verified["coordination_store_sha256"]
                != verified["coordination_store_sha256"]
                or published_verified["coordination_rearm_event_id"]
                != verified["coordination_rearm_event_id"]
            ):
                raise MaterializationError("published M9 pair differs from staging")
            receipt = _ensure_m9_migration_receipt(
                root,
                control,
                coordination,
                population,
                config,
                published_verified,
                validation_digest,
                pair_lock_held=True,
            )
            committed = True
            os.fsync(directory)
        finally:
            os.close(directory)
    except Exception:
        if (
            not committed
            and not stage_aliases_removed
            and not os.path.lexists(receipt_path)
        ):
            rollback_directory = os.open(
                control.parent,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                for published, expected_device, expected_inode in reversed(created):
                    if not os.path.lexists(published):
                        continue
                    published_stat = published.stat(follow_symlinks=False)
                    if (
                        published_stat.st_dev == expected_device
                        and published_stat.st_ino == expected_inode
                    ):
                        os.unlink(published)
                os.fsync(rollback_directory)
            finally:
                os.close(rollback_directory)
        raise
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)

    if not committed or receipt is None or published_verified is None:
        raise MaterializationError("M9 pair publication lacked its final marker")
    if not stage_aliases_removed:
        raise MaterializationError("M9 receipt preceded staging-alias removal")

    history = _ducklake_projection(
        root,
        config,
        {
            "program_definition_cid": population["program_definition_cid"],
            "projection_cid": published_verified["projection_cid"],
        },
    )
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only_control_and_coordination",
        "migration_required": False,
        "database_path": str(control),
        "coordination_path": str(coordination),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "prior_authority": prior,
        "plan_migration_event_id": plan_receipt.event_id,
        "migration_evidence_event_id": evidence.event_id,
        "task_rearm_event_id": published_verified["task_rearm_event_id"],
        "coordination_rearm_event_id": published_verified[
            "coordination_rearm_event_id"
        ],
        "migration_digest": migration_digest,
        "stage_cleanup_complete": True,
        "ducklake_history": history,
        "receipt": receipt,
        **published_verified,
    }


def _materialize_m8(
    root: Path,
    config_file: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Append and durably publish the source-only M8 successor."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m8_source_repair_authority(population, config)
    target = (root / str(config["database_program"]["store_id"])).resolve()
    if (
        str(config["database_program"]["store_id"])
        != authority["target_store_id"]
        or int(config["database_program"].get("store_generation") or 0)
        != _M8_TARGET_GENERATION
        or str(config["quack_owner"].get("database_path") or "")
        != authority["target_store_id"]
        or str(config["quack_owner"].get("store_id") or "")
        != authority["target_store_id"]
    ):
        raise MaterializationError("scheduler M8 target/generation binding differs")
    if not target.is_relative_to(root):
        raise MaterializationError("M8 target escapes the repository root")
    validation_digest = _m7_validation_digest(root, population)
    m5 = _verify_prior_store(root, config, population)
    m6 = _verify_frozen_m6_authority(root, config, population)
    m7 = _verify_frozen_m7_authority(root, config, population)
    prior_path = Path(m7["database_path"])
    if target.exists():
        verified = _verify_m8_store(
            target,
            population,
            config,
            validation_digest,
        )
        receipt = _ensure_m8_migration_receipt(
            root,
            target,
            population,
            config,
            verified,
            validation_digest,
        )
        history = _ducklake_projection(
            root,
            config,
            {
                "program_definition_cid": population["program_definition_cid"],
                "projection_cid": verified["projection_cid"],
            },
        )
        return {
            "schema": SCHEMA,
            "valid": True,
            "action": "verified_existing_noop",
            "migration_required": False,
            "database_path": str(target),
            "program_definition_cid": population["program_definition_cid"],
            "validation_digest": validation_digest,
            "m5_authority": m5,
            "m6_authority": m6,
            "prior_authority": m7,
            "receipt": receipt,
            "ducklake_history": history,
            **verified,
        }

    _assert_fresh_successor_operational_state(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    preserved_stages = sorted(target.parent.glob(target.name + ".installing.*"))
    if preserved_stages:
        raise MaterializationError(
            "preserved M8 staging attempt requires inspection: "
            + ", ".join(str(item) for item in preserved_stages)
        )
    stage = target.with_name(
        target.name + f".installing.{os.getpid()}.{validation_digest[-12:]}"
    )
    shutil.copy2(prior_path, stage)
    if _store_sha256(stage) != authority["prior_control_store_sha256"]:
        raise MaterializationError("staged M7 copy differs before M8 migration")
    before_semantic_authority = _semantic_authority_digest(stage)
    before_frozen_base_authority = _frozen_base_authority_digest(stage)
    before_append_surface = _append_surface_digest(stage)
    if (
        before_semantic_authority
        != authority["prior_semantic_authority_digest"]
        or before_frozen_base_authority
        != authority["prior_frozen_base_authority_digest"]
        or before_append_surface != authority["prior_append_surface_digest"]
    ):
        raise MaterializationError("staged M7 authority digest differs")

    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    source = DatabaseTaskSource(
        stage,
        install_schema=False,
        repository_tree_id=str(population["repository_tree_id"]),
        plan_root_cid=str(population["plan_root_cid"]),
        owner_id="sawm-r2-source-migrator",
    )
    try:
        operator = source.get_task("SAWM-000")
        if operator is None or operator.status != "completed" or operator.revision != 2:
            raise MaterializationError("M8 preserved operator completion differs")
        migration_body = _m8_migration_body(
            population,
            config,
            validation_digest,
        )
        migration_digest = _identity(migration_body)
        plan_delta = _m8_migration_plan_delta(population, config)
        plan_receipt = source.plans.append_revision(
            plan_cid=str(population["plan_root_cid"]),
            expected_revision=int(authority["prior_plan_revision"]),
            body={
                "current_source_binding_cid": population["source_binding"][
                    "source_binding_cid"
                ],
                "source_migration_revision": _M8_MIGRATION_REVISION,
                "source_migration_digest": migration_digest,
                "supersession_mode": _M8_SUPERSESSION_MODE,
            },
            delta=plan_delta,
        )
        evidence = source.record_evidence(
            task_cid=operator.task_cid,
            evidence_kind="operator_control_plane_source_migration",
            digest=migration_digest,
            body=migration_body,
        )
        unchanged = source.get_task(operator.task_cid)
        if (
            unchanged is None
            or unchanged.status != "completed"
            or unchanged.revision != 2
        ):
            raise MaterializationError("M8 migration changed operator task state")
    finally:
        source.close()
    after_semantic_authority = _semantic_authority_digest(stage)
    after_frozen_base_authority = _frozen_base_authority_digest(stage)
    if (
        after_semantic_authority != before_semantic_authority
        or after_frozen_base_authority != before_frozen_base_authority
    ):
        raise MaterializationError(
            "M8 source-only migration changed frozen authority"
        )
    verified = _verify_m8_store(
        stage,
        population,
        config,
        validation_digest,
    )
    if (
        int(verified["event_watermark"]) != _M8_TARGET_EVENT_WATERMARK
        or verified["projection_cid"] != _M8_EXPECTED_PROJECTION_CID
    ):
        raise MaterializationError("M8 emitted an unexpected event/projection suffix")
    if _store_sha256(prior_path) != authority["prior_control_store_sha256"]:
        raise MaterializationError("M8 migration changed frozen M7 authority")

    # Rebind the exact committed source immediately before publication.  A
    # failed final check intentionally leaves the staged bytes for audit.
    _assert_committed_clean_source(root, population)
    _assert_m8_source_delta(root, population, authority)
    with stage.open("rb") as staged_file:
        os.fsync(staged_file.fileno())

    lock = target.with_name(target.name + ".publish.lock")
    fd = None
    directory_fd = None
    try:
        fd = os.open(lock, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        directory_fd = os.open(target.parent, os.O_RDONLY)
        if target.exists():
            raise MigrationRequired(
                "another writer published M8; inspect it append-only"
            )
        # The staged events bind the source snapshot captured in `population`.
        # Recompute that binding while holding the publication lock so a clean
        # checkout to another commit cannot publish stale source evidence.
        _assert_committed_clean_source(root, population)
        _assert_m8_source_delta(root, population, authority)
        _assert_m8_prior_publication_anchor(root, authority, prior_path)
        os.link(stage, target)
        try:
            # Keep the staging link until the same binding has been observed
            # after publication. On drift, remove only the hard link created
            # above and retain the staged bytes for inspection.
            _assert_committed_clean_source(root, population)
            _assert_m8_source_delta(root, population, authority)
            _assert_m8_prior_publication_anchor(root, authority, prior_path)
        except Exception:
            stage_stat = stage.stat(follow_symlinks=False)
            target_stat = target.stat(follow_symlinks=False)
            if (
                stage_stat.st_dev != target_stat.st_dev
                or stage_stat.st_ino != target_stat.st_ino
            ):
                raise MaterializationError(
                    "M8 publication target changed during source revalidation"
                )
            os.unlink(target)
            os.fsync(directory_fd)
            raise
        os.fsync(directory_fd)
        os.unlink(stage)
        os.fsync(directory_fd)
    finally:
        if directory_fd is not None:
            os.close(directory_fd)
        if fd is not None:
            os.close(fd)
            lock.unlink(missing_ok=True)
    receipt = _ensure_m8_migration_receipt(
        root,
        target,
        population,
        config,
        verified,
        validation_digest,
    )
    history = _ducklake_projection(
        root,
        config,
        {
            "program_definition_cid": population["program_definition_cid"],
            "projection_cid": verified["projection_cid"],
        },
    )
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "migrated_append_only",
        "migration_required": False,
        "database_path": str(target),
        "program_definition_cid": population["program_definition_cid"],
        "validation_digest": validation_digest,
        "m5_authority": m5,
        "m6_authority": m6,
        "prior_authority": m7,
        "plan_migration_event_id": plan_receipt.event_id,
        "migration_evidence_event_id": evidence.event_id,
        "migration_digest": migration_digest,
        "semantic_authority_digest_before": before_semantic_authority,
        "semantic_authority_digest_after": after_semantic_authority,
        "frozen_base_authority_digest_before": before_frozen_base_authority,
        "frozen_base_authority_digest_after": after_frozen_base_authority,
        "prior_append_surface_digest": before_append_surface,
        "ducklake_history": history,
        "receipt": receipt,
        **verified,
    }


def _m18_portal_completion_persistence_authority(
    root: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Reconcile M18's exact authority across all three tracked controls."""

    expected = _expected_m18_portal_completion_persistence_authority()
    key = "portal_completion_persistence_successor_materialization"
    inventory = population.get("migration_inventory", {})
    seal = _load_json(
        root / "config/semantic_addressed_world_model_dependencies.seal.json"
    )
    if (
        config.get(key) != expected
        or not isinstance(inventory, Mapping)
        or inventory.get(key) != expected
        or seal.get(f"{key}_cid") != _identity(expected)
    ):
        raise MaterializationError(
            "M18 portal completion persistence authority differs across controls"
        )
    return expected


def _m18_name_status(root: Path, before: str, after: str) -> dict[str, str]:
    changed: dict[str, str] = {}
    for line in _git(
        root, "diff", "--name-status", "--no-renames", before, after, "--"
    ).splitlines():
        fields = line.split("\t")
        if len(fields) != 2 or fields[0] != "M" or fields[1] in changed:
            raise MaterializationError(
                f"M18 source delta contains a non-modification entry: {line}"
            )
        changed[fields[1]] = fields[0]
    return changed


def _assert_m18_source_delta(
    root: Path,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> None:
    """Seal M17 runtime merges, d24's repair, and the nine M18 controls."""

    prior_head = str(authority["prior_source_head"])
    runtime_head = str(authority["runtime_source_head"])
    precursor_head = str(authority["repair_precursor_source_commit"])
    repair_head = str(authority["repair_source_commit"])
    current_head = str(population["source_binding"]["head"])
    for head, tree_key in (
        (prior_head, "prior_source_tree"),
        (runtime_head, "runtime_source_tree"),
        (precursor_head, "repair_precursor_source_tree"),
        (repair_head, "repair_source_tree"),
    ):
        if _git(root, "rev-parse", f"{head}^{{tree}}") != authority[tree_key]:
            raise MaterializationError(f"M18 {tree_key} differs")
    if population["source_binding"].get("tree") != _git(
        root, "rev-parse", f"{current_head}^{{tree}}"
    ):
        raise MaterializationError("M18 current source tree binding differs")
    _git(root, "merge-base", "--is-ancestor", prior_head, runtime_head)
    _git(root, "merge-base", "--is-ancestor", runtime_head, precursor_head)
    _git(root, "merge-base", "--is-ancestor", precursor_head, repair_head)
    _git(root, "merge-base", "--is-ancestor", repair_head, current_head)

    if _m18_name_status(root, prior_head, runtime_head) != {
        "ipfs_datasets_py": "M"
    }:
        raise MaterializationError("M18 M17-runtime source chain differs")
    for transition in authority["accepted_runtime_source_transitions"]:
        implementation = str(transition["implementation_commit"])
        merge = str(transition["merge_commit"])
        _git(root, "merge-base", "--is-ancestor", prior_head, implementation)
        _git(root, "merge-base", "--is-ancestor", implementation, merge)
        _git(root, "merge-base", "--is-ancestor", merge, runtime_head)

    repair_paths = set(_M18_PORTAL_COMPLETION_REPAIR_BLOBS)
    if _m18_name_status(root, runtime_head, precursor_head) != {
        path: "M" for path in repair_paths
    }:
        raise MaterializationError("M18 portal repair precursor commit differs")
    if _m18_name_status(root, precursor_head, repair_head) != {
        path: "M" for path in repair_paths
    }:
        raise MaterializationError("M18 fail-closed repair successor differs")
    if _m18_name_status(root, runtime_head, repair_head) != {
        path: "M" for path in repair_paths
    }:
        raise MaterializationError("M18 exact portal repair commit differs")
    for path, expected_blob in _M18_PORTAL_COMPLETION_REPAIR_BLOBS.items():
        if (
            _git(root, "rev-parse", f"{repair_head}:{path}") != expected_blob
            or _git(root, "rev-parse", f"{current_head}:{path}") != expected_blob
        ):
            raise MaterializationError(f"M18 sealed repair blob differs: {path}")

    operator_paths = set(authority["operator_control_paths"])
    if operator_paths != set(_M18_OPERATOR_CONTROL_PATHS):
        raise MaterializationError("M18 authority does not name the nine controls")
    successor = _m18_name_status(root, repair_head, current_head)
    if successor != {path: "M" for path in operator_paths}:
        raise MaterializationError(
            "M18 post-repair source delta differs from the nine controls: "
            + json.dumps(
                {
                    "missing": sorted(operator_paths - set(successor)),
                    "unexpected": sorted(set(successor) - operator_paths),
                },
                sort_keys=True,
                separators=(",", ":"),
            )
        )
    authorized = set(authority["bounded_control_plane_repair_paths"])
    if authorized != repair_paths | operator_paths:
        raise MaterializationError("M18 bounded repair paths are not exact")
    combined = _m18_name_status(root, runtime_head, current_head)
    if combined != {path: "M" for path in authorized}:
        raise MaterializationError("M18 combined repair/control delta differs")

    if (
        _git(root, "rev-parse", f"{prior_head}:ipfs_datasets_py")
        != authority["prior_datasets_gitlink"]
        or _git(root, "rev-parse", f"{runtime_head}:ipfs_datasets_py")
        != authority["runtime_datasets_gitlink"]
        or _git(root, "rev-parse", f"{repair_head}:ipfs_datasets_py")
        != authority["runtime_datasets_gitlink"]
        or _git(root, "rev-parse", f"{current_head}:ipfs_datasets_py")
        != authority["runtime_datasets_gitlink"]
        or population["source_binding"].get("datasets_gitlink")
        != authority["runtime_datasets_gitlink"]
        or _git(root / "ipfs_datasets_py", "rev-parse", "HEAD^{tree}")
        != authority["runtime_datasets_tree"]
    ):
        raise MaterializationError("M18 datasets authority differs")
    for head in (prior_head, runtime_head, repair_head, current_head):
        if _git(root, "rev-parse", f"{head}:ipfs_kit_py") != authority[
            "prior_kit_gitlink"
        ]:
            raise MaterializationError("M18 kit gitlink authority differs")
    if (
        population["source_binding"].get("kit_gitlink")
        != authority["prior_kit_gitlink"]
        or _git(root / "ipfs_kit_py", "rev-parse", "HEAD^{tree}")
        != authority["prior_kit_tree"]
    ):
        raise MaterializationError("M18 kit authority differs")


def _m18_target_paths(
    root: Path,
    config: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[Path, Path]:
    """Resolve only M18's fresh generation-19 runtime root."""

    program = config.get("database_program")
    owner = config.get("quack_owner")
    runtime = config.get("runtime_paths")
    target_root = str(authority["target_runtime_root"])
    expected_runtime = {
        "root": target_root,
        "state": f"{target_root}/state",
        "worktrees": f"{target_root}/worktrees",
        "merge_queue": f"{target_root}/merge-queue",
        "logs": f"{target_root}/logs",
        "generated_runtime_artifacts_are_completion_authority": False,
    }
    if (
        not isinstance(program, Mapping)
        or not isinstance(owner, Mapping)
        or program.get("store_id") != authority["target_store_id"]
        or str(program.get("store_generation") or "") != "19"
        or program.get("quack_endpoint") != "quack:127.0.0.1:24061"
        or program.get("event_store_path") != f"{target_root}/events"
        or program.get("runtime_registry_path") != f"{target_root}/registry"
        or program.get("worktree_root") != f"{target_root}/worktrees"
        or owner.get("database_path") != authority["target_store_id"]
        or owner.get("store_id") != authority["target_store_id"]
        or owner.get("state_dir") != f"{target_root}/quack-owner"
        or int(owner.get("port") or 0) != _M18_TARGET_QUACK_PORT
        or runtime != expected_runtime
    ):
        raise MaterializationError(
            "scheduler M18 store, owner, or runtime-root binding differs"
        )
    control = _confined_leaf(
        root, str(authority["target_store_id"]), noun="M18 control store"
    )
    coordination = _confined_leaf(
        root,
        str(authority["target_coordination_store_id"]),
        noun="M18 coordination store",
    )
    if (
        control.parent != coordination.parent
        or coordination != control.with_name("control.coordination.duckdb")
        or str(control.parent.relative_to(root)) != target_root
    ):
        raise MaterializationError("scheduler M18 store pair is not confined")
    return control, coordination


