    task_rearm_event_ids["failure"] = events[2]["id"]
    task_rearm_event_ids["retry"] = events[3]["id"]
    task_rearm_receipt_cids["failure"] = content_identity(_m23_failure_receipt())
    task_rearm_receipt_cids["retry"] = content_identity(_m23_task_rearm_receipt())

    semantic = _semantic_authority_digest(control)
