def _assert_m23_target_clean(control: Path, coordination: Path) -> None:
    """Reject every mutable runtime sidecar at the M23 target."""

    forbidden = (
        control.with_name(control.name + ".wal"),
        coordination.with_name(coordination.name + ".wal"),
        control.with_name("control.execution.duckdb"),
        control.with_name("control.execution.duckdb.wal"),
        control.with_name("control.read-replica.duckdb"),
        control.with_name("control.read-replica.duckdb.wal"),
        control.with_name(f".{control.name}.state-owner.json"),
        control.parent / "state",
        control.parent / "events",
        control.parent / "registry",
        control.parent / "worktrees",
        control.parent / "merge-queue",
        control.parent / "logs",
        control.parent / "quack-owner",
    )
    if any(os.path.lexists(path) for path in forbidden):
        raise MigrationRequired("M23 target has a forbidden mutable sidecar")


def _assert_m23_no_staging_or_pending(control: Path) -> None:
    receipt = control.parent / "migration-receipt.json"
    if tuple(control.parent.glob(".m23-installing.*")) or tuple(
        control.parent.glob(f".{receipt.name}.*.tmp")
    ):
        raise MigrationRequired("M23 retained a staging or receipt temporary")


def _assert_m23_no_staging(control: Path) -> None:
    """Reject private stages while permitting exact receipt recovery."""

    if tuple(control.parent.glob(".m23-installing.*")):
        raise MigrationRequired("M23 retained a private staging artifact")


def _verify_m23_store_pair(
    root: Path,
    control: Path,
    coordination: Path,
    prior_control: Path,
    prior_coordination: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    """Verify published M23 only through hash-checked disposable copies."""

    _assert_m23_target_clean(control, coordination)
    _assert_offline(control)
    if _m18_prior_listener_is_active(_M23_TARGET_QUACK_PORT):
        raise MigrationRequired("M23 target listener appeared before verification")
    before = {
        "control": _stable_regular_sha256(
            control, root=root, noun="published M23 control", required_link_count=1
        ),
        "coordination": _stable_regular_sha256(
            coordination,
            root=root,
            noun="published M23 coordination",
            required_link_count=1,
        ),
        "prior_control": _stable_regular_sha256(
            prior_control,
            root=root,
            noun="stopped M22 predecessor control",
            required_link_count=1,
        ),
        "prior_coordination": _stable_regular_sha256(
            prior_coordination,
            root=root,
            noun="M22 predecessor coordination",
            required_link_count=1,
        ),
    }
    with tempfile.TemporaryDirectory(prefix="sawm-r2-m23-verify-", dir="/tmp") as td:
        copy_root = Path(td)
        copies: dict[str, Path] = {}
        for key, source in (
            ("control", control),
            ("coordination", coordination),
            ("prior_control", prior_control),
            ("prior_coordination", prior_coordination),
        ):
            target = copy_root / f"{key}.duckdb"
            shutil.copyfile(source, target)
            if _stable_regular_sha256(
                target,
                root=copy_root,
                noun=f"M23 {key} copy",
                required_link_count=1,
            ) != before[key]:
                raise MaterializationError("M23 verification copy differs")
            copies[key] = target
        verified = _verify_m23_store_pair_copy(
            copies["control"],
            copies["coordination"],
            copies["prior_control"],
            copies["prior_coordination"],
            population,
            config,
            validation_digest,
        )
    after = {
        "control": _stable_regular_sha256(
            control, root=root, noun="published M23 control", required_link_count=1
        ),
        "coordination": _stable_regular_sha256(
            coordination,
            root=root,
            noun="published M23 coordination",
            required_link_count=1,
        ),
        "prior_control": _stable_regular_sha256(
            prior_control,
            root=root,
            noun="stopped M22 predecessor control",
            required_link_count=1,
        ),
        "prior_coordination": _stable_regular_sha256(
            prior_coordination,
            root=root,
            noun="M22 predecessor coordination",
            required_link_count=1,
        ),
    }
    _assert_m23_target_clean(control, coordination)
    if _m18_prior_listener_is_active(_M23_TARGET_QUACK_PORT):
        raise MigrationRequired("M23 target listener appeared during verification")
    if before != after:
        raise MaterializationError("M23 verification changed published authority")
    _assert_offline(control)
    return verified


