def _assert_m32_source_delta(
    root: Path,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> None:
    """Require exactly one nine-control repair commit and one reseal."""

    identities = (
        _M32_INITIAL_CONTROL_COMMIT,
        _M32_INITIAL_CONTROL_TREE,
        *tuple(_M32_INITIAL_CONTROL_BLOBS.values()),
    )
    if any(value == "0" * 40 or re.fullmatch(r"[0-9a-f]{40}", value) is None for value in identities):
        raise MaterializationError("M32 source identities are not resealed")
    current = str(population["source_binding"]["head"])
    chain = authority.get("source_chain")
    control_paths = set(authority.get("operator_control_paths") or ())
    current_parents = _git(root, "rev-list", "--parents", "-n", "1", current).split()
    initial_parents = _git(
        root, "rev-list", "--parents", "-n", "1", _M32_INITIAL_CONTROL_COMMIT
    ).split()
    if (
        current in {_M32_BASE_CONTROL_COMMIT, _M32_INITIAL_CONTROL_COMMIT}
        or not isinstance(chain, Mapping)
        or control_paths != set(_M32_OPERATOR_CONTROL_PATHS)
        or _M32_OPERATOR_CONTROL_PATHS != _M31_OPERATOR_CONTROL_PATHS
        or chain.get("base_control_commit") != _M32_BASE_CONTROL_COMMIT
        or chain.get("base_control_tree") != _M32_BASE_CONTROL_TREE
        or chain.get("initial_control_commit") != _M32_INITIAL_CONTROL_COMMIT
        or chain.get("initial_control_tree") != _M32_INITIAL_CONTROL_TREE
        or chain.get("initial_control_blobs") != dict(_M32_INITIAL_CONTROL_BLOBS)
        or chain.get("final_reseal_parent") != _M32_INITIAL_CONTROL_COMMIT
        or initial_parents != [_M32_INITIAL_CONTROL_COMMIT, _M32_BASE_CONTROL_COMMIT]
        or current_parents != [current, _M32_INITIAL_CONTROL_COMMIT]
        or _git(root, "rev-parse", f"{_M32_BASE_CONTROL_COMMIT}^{{tree}}")
        != _M32_BASE_CONTROL_TREE
        or _git(root, "rev-parse", f"{_M32_INITIAL_CONTROL_COMMIT}^{{tree}}")
        != _M32_INITIAL_CONTROL_TREE
        or _m27_name_status(root, _M32_BASE_CONTROL_COMMIT, _M32_INITIAL_CONTROL_COMMIT)
        != {path: "M" for path in control_paths}
        or _m27_name_status(root, _M32_INITIAL_CONTROL_COMMIT, current)
        != {path: "M" for path in control_paths}
        or population["source_binding"].get("tree")
        != _git(root, "rev-parse", f"{current}^{{tree}}")
    ):
        raise MaterializationError("M32 exact control-repair/reseal source chain differs")
    for path, oid in _M32_INITIAL_CONTROL_BLOBS.items():
        if _git(root, "rev-parse", f"{_M32_INITIAL_CONTROL_COMMIT}:{path}") != oid:
            raise MaterializationError(f"M32 initial-control blob differs: {path}")
    for dependency, gitlink_key, tree_key, population_key in (
        ("ipfs_datasets_py", "current_datasets_gitlink", "current_datasets_tree", "datasets_gitlink"),
        ("ipfs_kit_py", "current_kit_gitlink", "current_kit_tree", "kit_gitlink"),
    ):
        gitlink = str(authority[gitlink_key])
        if (
            any(
                _git(root, "rev-parse", f"{head}:{dependency}") != gitlink
                for head in (_M32_BASE_CONTROL_COMMIT, _M32_INITIAL_CONTROL_COMMIT, current)
            )
            or population["source_binding"].get(population_key) != gitlink
            or _git(root / dependency, "rev-parse", f"{gitlink}^{{tree}}")
            != authority[tree_key]
        ):
            raise MaterializationError(f"M32 {dependency} authority differs")


